import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import { useNotifications } from '../../hooks/useNotifications';
import api from '../../api/client';

function Toggle({ label, checked, onChange, disabled }) {
  return (
    <label className={`flex items-center justify-between py-3 ${disabled ? 'opacity-40' : ''}`}>
      <span className="text-base text-gray-700 dark:text-slate-200">{label}</span>
      <button
        type="button"
        disabled={disabled}
        onClick={() => onChange(!checked)}
        className={`relative w-12 h-7 rounded-full transition-colors ${checked ? 'bg-accent' : 'bg-gray-300'}`}
      >
        <span className={`absolute top-0.5 left-0.5 w-6 h-6 bg-white rounded-full shadow transition-transform ${checked ? 'translate-x-5' : ''}`} />
      </button>
    </label>
  );
}

export default function NotificationSettings() {
  const navigate = useNavigate();
  const { currentMember } = useFamily();
  const { permissionGranted, requestPermission, showNotification } = useNotifications();

  const [prefs, setPrefs] = useState({
    enabled: 1,
    homework_reminder: 1,
    routine_reminder: 1,
    quiz_reminder: 1,
    plan_reminder: 1,
    photo_reminder: 1,
    quiet_start: '21:00',
    quiet_end: '07:00',
  });
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (!currentMember?.id) return;
    api.get(`/notifications/preferences/${currentMember.id}`)
      .then(res => {
        if (res.data.success) setPrefs(res.data.preferences);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [currentMember?.id]);

  async function savePrefs(newPrefs) {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    setSaved(false);
    try {
      await api.put(`/notifications/preferences/${currentMember.id}`, updated);
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    } catch {}
  }

  function handleTest() {
    if (!permissionGranted) {
      requestPermission().then(granted => {
        if (granted) {
          showNotification('Foxie dit bonjour !', 'Les notifications fonctionnent parfaitement.', 'test-notification', '/');
        }
      });
    } else {
      showNotification('Foxie dit bonjour !', 'Les notifications fonctionnent parfaitement.', 'test-notification', '/');
    }
  }

  if (!currentMember) return null;
  if (loading) return <div className="text-center py-8 text-gray-400">Chargement...</div>;

  const enabled = !!prefs.enabled;

  return (
    <div className="flex flex-col gap-4 pb-4">
      {/* Header */}
      <div className="flex items-center gap-3">
        <button onClick={() => navigate(-1)} className="text-2xl text-gray-500 dark:text-slate-400">&#8592;</button>
        <h1 className="text-xl font-bold text-gray-800 dark:text-slate-100">Notifications</h1>
        {saved && <span className="text-sm text-green-600 ml-auto">Enregistre !</span>}
      </div>

      {/* Permission banner */}
      {!permissionGranted && (
        <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4">
          <p className="text-base text-amber-800 mb-2">Les notifications ne sont pas encore autorisees.</p>
          <button
            onClick={requestPermission}
            className="bg-accent text-white px-4 py-2 rounded-full text-base font-medium"
          >
            Autoriser les notifications
          </button>
        </div>
      )}

      {/* Main settings card */}
      <div className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm">
        <Toggle
          label="Activer les notifications"
          checked={enabled}
          onChange={(v) => savePrefs({ enabled: v ? 1 : 0 })}
        />

        <div className="border-t border-gray-100 mt-1 pt-1">
          <Toggle
            label="Rappel devoirs"
            checked={!!prefs.homework_reminder}
            onChange={(v) => savePrefs({ homework_reminder: v ? 1 : 0 })}
            disabled={!enabled}
          />
          <Toggle
            label="Rappel photos cours"
            checked={!!prefs.photo_reminder}
            onChange={(v) => savePrefs({ photo_reminder: v ? 1 : 0 })}
            disabled={!enabled}
          />
          <Toggle
            label="Routine du soir"
            checked={!!prefs.routine_reminder}
            onChange={(v) => savePrefs({ routine_reminder: v ? 1 : 0 })}
            disabled={!enabled}
          />
          <Toggle
            label="Quiz du soir"
            checked={!!prefs.quiz_reminder}
            onChange={(v) => savePrefs({ quiz_reminder: v ? 1 : 0 })}
            disabled={!enabled}
          />
          <Toggle
            label="Plan de progres"
            checked={!!prefs.plan_reminder}
            onChange={(v) => savePrefs({ plan_reminder: v ? 1 : 0 })}
            disabled={!enabled}
          />
        </div>

        {/* Quiet hours */}
        <div className={`border-t border-gray-100 mt-2 pt-3 ${!enabled ? 'opacity-40' : ''}`}>
          <p className="text-base font-semibold text-gray-700 dark:text-slate-200 mb-2">Heures calmes</p>
          <div className="flex items-center gap-3">
            <div className="flex-1">
              <label className="text-sm text-gray-500 dark:text-slate-400">Debut</label>
              <input
                type="time"
                value={prefs.quiet_start || '21:00'}
                onChange={(e) => savePrefs({ quiet_start: e.target.value })}
                disabled={!enabled}
                className="w-full border border-gray-200 rounded-xl px-3 py-2 text-base"
              />
            </div>
            <span className="text-gray-400 mt-5">-</span>
            <div className="flex-1">
              <label className="text-sm text-gray-500 dark:text-slate-400">Fin</label>
              <input
                type="time"
                value={prefs.quiet_end || '07:00'}
                onChange={(e) => savePrefs({ quiet_end: e.target.value })}
                disabled={!enabled}
                className="w-full border border-gray-200 rounded-xl px-3 py-2 text-base"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Test button */}
      <button
        onClick={handleTest}
        className="bg-accent/10 text-accent font-semibold py-3 rounded-2xl text-base active:scale-[0.97] transition-transform"
      >
        Tester une notification
      </button>

      <p className="text-sm text-gray-400 text-center">
        Les notifications s'affichent aux bons moments de la journee pour rappeler devoirs, routine et quiz.
      </p>
    </div>
  );
}
