import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import { useTheme } from '../../context/ThemeContext';
import api from '../../api/client';

function SectionCard({ icon, title, subtitle, onClick, badge }) {
  return (
    <button onClick={onClick}
      className="w-full bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm text-left active:scale-[0.98] transition-transform flex items-center gap-4">
      <span className="text-2xl shrink-0">{icon}</span>
      <span className="flex-1 min-w-0">
        <span className="block font-medium text-base text-gray-800 dark:text-slate-100">{title}</span>
        <span className="block text-sm text-gray-500 dark:text-slate-400 truncate">{subtitle}</span>
      </span>
      {badge && (
        <span className="text-xs bg-accent/10 text-accent px-2 py-1 rounded-full shrink-0">{badge}</span>
      )}
      <span className="text-gray-400 dark:text-slate-500 shrink-0">›</span>
    </button>
  );
}

export default function SettingsPage() {
  const navigate = useNavigate();
  const { currentMember, childMembers, clearMember } = useFamily();
  const { dark, toggle: toggleDark } = useTheme();
  const [edStatus, setEdStatus] = useState(null);

  useEffect(() => {
    api.get('/ecoledirecte/status')
      .then(res => setEdStatus(res.data))
      .catch(() => setEdStatus({ connected: false, accounts: [] }));
  }, []);

  const activeAccounts = (edStatus?.accounts || []).filter(a => a.sessionActive);
  const edConnected = activeAccounts.length > 0;
  const edBadge = edConnected ? `${activeAccounts.length} actif${activeAccounts.length > 1 ? 's' : ''}` : 'Non connecté';

  return (
    <div className="space-y-5 pb-4">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-medium text-gray-800 dark:text-slate-100">Réglages</h1>
          <p className="text-sm text-gray-400 dark:text-slate-500">Synchro, profils, notifications</p>
        </div>
        <button onClick={() => { clearMember(); navigate('/welcome', { replace: true }); }}
          className="text-sm text-accent bg-accent/10 px-3 py-1.5 rounded-full">
          Changer
        </button>
      </div>

      <div className="space-y-3">
        <SectionCard
          icon="🏫"
          title="Synchro école"
          subtitle="EcoleDirecte — devoirs, notes, emploi du temps"
          badge={edBadge}
          onClick={() => navigate('/reglages/ecole')}
        />
        <SectionCard
          icon="👨‍👩‍👧"
          title="Profils des enfants"
          subtitle={childMembers.length > 0 ? childMembers.map(c => c.name).join(', ') : 'Aucun enfant'}
          onClick={() => navigate('/welcome')}
        />
        <SectionCard
          icon="🔔"
          title="Notifications"
          subtitle="Rappels devoirs, défi du soir, heures calmes"
          onClick={() => navigate('/reglages/notifications')}
        />

        <div className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm flex items-center gap-4">
          <span className="text-2xl shrink-0">{dark ? '🌙' : '☀️'}</span>
          <span className="flex-1">
            <span className="block font-medium text-base text-gray-800 dark:text-slate-100">Apparence</span>
            <span className="block text-sm text-gray-500 dark:text-slate-400">{dark ? 'Mode sombre activé' : 'Mode clair activé'}</span>
          </span>
          <button onClick={toggleDark}
            className={`relative w-12 h-7 rounded-full transition-colors shrink-0 ${dark ? 'bg-accent' : 'bg-gray-300'}`}
            aria-label="Basculer mode sombre">
            <span className={`absolute top-0.5 left-0.5 w-6 h-6 bg-white rounded-full shadow transition-transform ${dark ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      </div>

      <div className="pt-2 text-center">
        <p className="text-xs text-gray-400 dark:text-slate-500">
          Compte actif : {currentMember?.name || '—'}
        </p>
      </div>
    </div>
  );
}
