import { useEffect, useRef, useState } from 'react';
import { Transformer } from 'markmap-lib';
import { Markmap, deriveOptions } from 'markmap-view';
import { useTheme } from '../../context/ThemeContext';

const transformer = new Transformer();

/**
 * Convert our app's mindmap JSON ({central, branches: [{label, items|sub_branches}]})
 * into Markdown with nested bullet structure that Markmap can ingest.
 */
function jsonToMarkdown(data) {
  if (!data) return '# Carte mentale';
  const central = data.central_topic || data.central || data.title || 'Carte mentale';

  // Escape pipes and backticks that would break markdown
  const safe = (s) => String(s || '').replace(/[\n\r]+/g, ' ').trim();

  let md = `# ${safe(central)}\n`;

  const branches = data.branches || [];
  for (const b of branches) {
    md += `\n## ${safe(b.label || b.title || 'Branche')}\n`;
    const items = b.sub_branches || b.items || [];
    for (const item of items) {
      if (item == null) continue;
      if (typeof item === 'string') {
        md += `- ${safe(item)}\n`;
      } else {
        md += `- ${safe(item.label || item.title || JSON.stringify(item))}\n`;
        const details = item.details || item.children || [];
        for (const d of details) {
          if (typeof d === 'string') md += `  - ${safe(d)}\n`;
          else md += `  - ${safe(d.label || d.title || '')}\n`;
        }
      }
    }
  }

  // Append optional summary as a separate branch
  if (data.summary) {
    md += `\n## En résumé\n- ${safe(data.summary)}\n`;
  }

  return md;
}

const COLOR_LIGHT = ['#7C9082', '#C4A484', '#4A90D9', '#E8A0BF', '#A88BC8', '#F2A65A', '#5BA89B', '#D97757'];
const COLOR_DARK = ['#a3c5ab', '#d9bf99', '#7fb0e0', '#f0b9d2', '#c4a8d6', '#f5c08a', '#86c4ba', '#e89481'];

export default function MindMapMarkmap({ data, height = 460 }) {
  const svgRef = useRef(null);
  const mmRef = useRef(null);
  const { dark } = useTheme();
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!svgRef.current || !data) return;

    setError(false);

    try {
      const md = jsonToMarkdown(data);
      const { root } = transformer.transform(md);

      const colorPalette = dark ? COLOR_DARK : COLOR_LIGHT;
      const options = deriveOptions({
        color: colorPalette,
        colorFreezeLevel: 2,
        spacingHorizontal: 90,
        spacingVertical: 12,
        paddingX: 12,
        duration: 300,
        initialExpandLevel: -1, // expand all
      });

      // Cleanup previous instance if any
      if (mmRef.current) {
        try { mmRef.current.destroy(); } catch {}
        mmRef.current = null;
      }

      // Clear SVG
      svgRef.current.innerHTML = '';

      const mm = Markmap.create(svgRef.current, options, root);
      mmRef.current = mm;

      // Fit after render
      setTimeout(() => {
        try { mm.fit(); } catch {}
      }, 80);
    } catch (err) {
      console.error('Markmap render error:', err);
      setError(true);
    }

    return () => {
      if (mmRef.current) {
        try { mmRef.current.destroy(); } catch {}
        mmRef.current = null;
      }
    };
  }, [data, dark]);

  if (error) {
    return (
      <div className="text-center py-6 text-sm text-texte-light dark:text-slate-400">
        Carte mentale indisponible.
      </div>
    );
  }

  return (
    <div className={`rounded-xl border ${dark ? 'border-slate-700 bg-slate-950' : 'border-gray-100 bg-white'} overflow-hidden`}>
      <svg
        ref={svgRef}
        style={{ width: '100%', height: `${height}px`, display: 'block' }}
      />
      <p className={`text-[11px] text-center py-1.5 ${dark ? 'text-slate-500' : 'text-gray-400'}`}>
        Pince pour zoomer · Glisse pour déplacer · Clique un nœud pour replier
      </p>
    </div>
  );
}
