import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import api from '../../api/client';

export default function ParentDashboardPage() {
  const navigate = useNavigate();
  const { currentMember, childMembers, clearMember } = useFamily();
  const [childStats, setChildStats] = useState({});
  const [aiInfo, setAiInfo] = useState(null);

  useEffect(() => {
    // Load basic stats for each child
    childMembers.forEach(async (child) => {
      try {
        const res = await api.get(`/kb/summary/${child.id}`);
        if (res.data.success) {
          setChildStats(prev => ({ ...prev, [child.id]: res.data }));
        }
      } catch {}
    });
  }, [childMembers]);

  useEffect(() => {
    // Modèle IA actif (ligne discrète en bas)
    api.get('/llm/status')
      .then(res => {
        const t = res.data?.tiers?.smart;
        if (t?.model) setAiInfo({ model: t.model, provider: t.provider });
      })
      .catch(() => {});
  }, []);

  return (
    <div className="space-y-5">
      {/* Greeting */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-medium text-gray-800 dark:text-slate-100">Bonjour {currentMember?.name}</h1>
          <p className="text-base text-gray-400 dark:text-slate-500">Aujourd’hui</p>
        </div>
        <button onClick={() => { clearMember(); navigate('/welcome', { replace: true }); }}
          className="text-sm text-accent bg-accent/10 px-3 py-1.5 rounded-full">
          Changer
        </button>
      </div>

      <button
        onClick={() => navigate('/bilan')}
        className="w-full bg-white/90 dark:bg-slate-900 rounded-2xl p-4 border border-gray-100 dark:border-slate-700 shadow-sm text-left active:scale-[0.98]"
      >
        <p className="text-sm text-gray-400 dark:text-slate-500 mb-1">Priorité du jour</p>
        <p className="text-lg font-medium text-gray-800 dark:text-slate-100">Voir ce que Foxie a compris cette semaine</p>
        <p className="text-base text-gray-500 dark:text-slate-400 mt-1">Progrès, points à surveiller et une action simple pour ce soir.</p>
      </button>

      {/* Children overview */}
      <div>
        <h2 className="font-medium text-lg text-gray-700 dark:text-slate-200 mb-3">Mes enfants</h2>
        <div className="space-y-2">
          {childMembers.map(child => {
            const stats = childStats[child.id];
            const pendingHw = stats?.pendingHomework?.length || 0;
            return (
              <button key={child.id} onClick={() => navigate('/bilan')}
                className="w-full bg-white/90 dark:bg-slate-900 rounded-2xl p-4 border border-gray-100 dark:border-slate-700 shadow-sm flex items-center gap-4 active:scale-[0.98] text-left">
                <div className="w-12 h-12 rounded-full bg-accent/10 flex items-center justify-center text-xl font-medium text-accent">
                  {child.name.charAt(0)}
                </div>
                <div className="flex-1">
                  <p className="font-medium text-lg text-gray-800 dark:text-slate-100">{child.name}</p>
                  <p className="text-sm text-gray-400 dark:text-slate-500">{child.grade}</p>
                </div>
                {pendingHw > 0 && (
                  <span className="bg-red-50 text-red-600 text-sm px-2.5 py-1 rounded-full">
                    {pendingHw} devoir{pendingHw > 1 ? 's' : ''}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {aiInfo && (
        <p className="text-center text-xs text-gray-300 dark:text-slate-600 pt-1">
          IA · {aiInfo.model}
        </p>
      )}
    </div>
  );
}
