import axios from 'axios';

// Auto-detect API base URL:
// - In production (same server): use relative /api
// - In dev (different port): use hostname:3002
const isDev = process.env.NODE_ENV === 'development';
const API_BASE = isDev
  ? `http://${window.location.hostname}:3002/api`
  : '/api';

const api = axios.create({
  baseURL: API_BASE,
  headers: { 'Content-Type': 'application/json' },
});

// Export base for non-axios fetch calls (avatar speak, etc.)
export const API_ROOT = isDev
  ? `http://${window.location.hostname}:3002`
  : '';

// ─── Code d'accès familial ───
export const ACCESS_TOKEN_KEY = 'ff_access_token';
export function getAccessToken() {
  try { return localStorage.getItem(ACCESS_TOKEN_KEY) || ''; } catch { return ''; }
}
export function setAccessToken(token) {
  try { localStorage.setItem(ACCESS_TOKEN_KEY, token); } catch {}
}
export function clearAccessToken() {
  try { localStorage.removeItem(ACCESS_TOKEN_KEY); } catch {}
}

// Joindre le token à chaque requête
api.interceptors.request.use((config) => {
  const token = getAccessToken();
  if (token) config.headers['x-access-token'] = token;
  return config;
});

// Si le code est refusé (401), on efface le token et on revient à l'écran de connexion
api.interceptors.response.use(
  (res) => res,
  (error) => {
    if (error?.response?.status === 401) {
      clearAccessToken();
      if (!window.location.pathname.startsWith('/login')) {
        window.location.reload();
      }
    }
    return Promise.reject(error);
  }
);

export default api;
