import { useState, useEffect, useCallback } from 'react';
import api from '../../api/client';
import { formatDate, getDayName } from '../../utils/dateUtils';

export default function HomeworkView({ studentId }) {
  const [homework, setHomework] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const loadHomework = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get(`/ecoledirecte/homework${studentId ? `?studentId=${studentId}` : ''}`);
      if (res.data.success) {
        setHomework(res.data.homework);
      } else {
        setError(res.data.error || 'Erreur de chargement');
      }
    } catch (err) {
      if (err.response?.data?.error === 'SESSION_EXPIRED') {
        setError('Session expiree. Veuillez vous reconnecter.');
      } else {
        setError('Impossible de charger les devoirs');
      }
    } finally {
      setLoading(false);
    }
  }, [studentId]);

  useEffect(() => {
    loadHomework();
  }, [loadHomework]);

  if (loading) {
    return (
      <div className="text-center py-8">
        <p className="text-2xl animate-bounce">📝</p>
        <p className="text-sm text-texte-light mt-2">Chargement des devoirs...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center">
        <p className="text-sm text-red-600">{error}</p>
        <button onClick={loadHomework} className="text-accent text-sm mt-2 font-semibold">
          Reessayer
        </button>
      </div>
    );
  }

  if (!homework || Object.keys(homework).length === 0) {
    return (
      <div className="text-center py-8">
        <p className="text-3xl">🎉</p>
        <p className="text-sm text-texte-light mt-2">Aucun devoir a venir !</p>
      </div>
    );
  }

  // Sort dates
  const sortedDates = Object.keys(homework).sort();

  return (
    <div className="space-y-4">
      {sortedDates.map(date => {
        const items = homework[date];
        const d = new Date(date);
        const dayName = getDayName(d.getDay(), true);

        return (
          <div key={date}>
            <h3 className="font-semibold text-sm text-texte-light mb-2">
              {dayName} {formatDate(date)}
            </h3>
            <div className="space-y-2">
              {items.map((item, i) => (
                <div
                  key={i}
                  className={`bg-blanc rounded-xl p-4 border border-border ${
                    item.done ? 'opacity-60' : ''
                  }`}
                >
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`w-2 h-2 rounded-full ${item.done ? 'bg-green-400' : 'bg-accent'}`} />
                    <span className="font-semibold text-sm">{item.subject}</span>
                    {item.done && (
                      <span className="text-xs bg-green-100 text-green-600 px-1.5 py-0.5 rounded-full">
                        Fait
                      </span>
                    )}
                  </div>
                  {item.description && (
                    <p className="text-sm text-texte-light ml-4 leading-relaxed">
                      {item.description}
                    </p>
                  )}
                  {item.documents && item.documents.length > 0 && (
                    <div className="ml-4 mt-2 flex gap-1">
                      {item.documents.map((doc, j) => (
                        <span key={j} className="text-xs bg-accent-light text-accent px-2 py-0.5 rounded-full">
                          📎 {doc.name}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}
