import { useState } from 'react';
import api from '../../api/client';

export default function LoginForm({ onSuccess, savedAccount }) {
  const [username, setUsername] = useState(savedAccount?.username || '');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // QCM double-auth state
  const [qcmStep, setQcmStep] = useState(false);
  const [question, setQuestion] = useState('');
  const [propositions, setPropositions] = useState([]);
  const [rawPropositions, setRawPropositions] = useState([]);
  const [selectedAnswer, setSelectedAnswer] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    if (!username || !password) return;

    setLoading(true);
    setError('');

    try {
      const res = await api.post('/ecoledirecte/login', { username, password });

      if (res.data.success) {
        onSuccess();
      } else if (res.data.needDoubleAuth) {
        // Need QCM - fetch the question
        await fetchQcmQuestion();
      } else {
        setError(res.data.error || 'Erreur de connexion');
      }
    } catch (err) {
      const errMsg = err.response?.data?.error || err.message || 'Impossible de se connecter';
      if (errMsg.includes('ENOTFOUND') || errMsg.includes('network')) {
        setError('Impossible de joindre le serveur EcoleDirecte. Verifiez votre connexion internet.');
      } else if (errMsg.includes('timeout') || errMsg.includes('ETIMEDOUT')) {
        setError('Le serveur EcoleDirecte ne repond pas. Reessayez dans quelques minutes.');
      } else {
        setError(errMsg);
      }
    } finally {
      setLoading(false);
    }
  }

  async function fetchQcmQuestion() {
    try {
      const res = await api.post('/ecoledirecte/doubleauth/question', { username });
      if (res.data.success) {
        setQuestion(res.data.question);
        setPropositions(res.data.propositions);
        setRawPropositions(res.data.rawPropositions);
        setQcmStep(true);
        setError('');
      } else {
        setError(res.data.error || 'Impossible de recuperer la question de securite');
      }
    } catch (err) {
      setError('Erreur lors de la recuperation de la question');
    }
  }

  async function handleQcmSubmit() {
    if (selectedAnswer === null) return;

    setLoading(true);
    setError('');

    try {
      const rawAnswer = rawPropositions[selectedAnswer];
      const res = await api.post('/ecoledirecte/doubleauth/answer', {
        username,
        password,
        answer: rawAnswer,
      });

      if (res.data.success) {
        onSuccess();
      } else {
        setError(res.data.error || 'Mauvaise reponse. Reessayez.');
        setSelectedAnswer(null);
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Erreur lors de la verification');
    } finally {
      setLoading(false);
    }
  }

  // QCM Step
  if (qcmStep) {
    return (
      <div className="bg-blanc rounded-2xl p-6 border border-border">
        <div className="text-center mb-6">
          <span className="text-4xl">🔐</span>
          <h3 className="font-bold text-lg mt-2">Verification de securite</h3>
          <p className="text-xs text-texte-light mt-1">
            EcoleDirecte demande une verification pour ce nouvel appareil
          </p>
        </div>

        <div className="bg-fond rounded-xl p-4 mb-4">
          <p className="text-sm font-semibold text-center">{question}</p>
        </div>

        <div className="space-y-2 mb-4">
          {propositions.map((prop, i) => (
            <button
              key={i}
              onClick={() => setSelectedAnswer(i)}
              className={`w-full text-left p-3 rounded-xl border-2 text-sm transition-all ${
                selectedAnswer === i
                  ? 'border-accent bg-accent-light font-semibold'
                  : 'border-border bg-blanc hover:border-accent-light'
              }`}
            >
              {prop}
            </button>
          ))}
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-4">
            <p className="text-sm text-red-600">{error}</p>
          </div>
        )}

        <button
          onClick={handleQcmSubmit}
          disabled={loading || selectedAnswer === null}
          className="w-full bg-accent text-white py-3 rounded-xl font-semibold text-sm disabled:opacity-50 transition-opacity"
        >
          {loading ? 'Verification...' : 'Valider'}
        </button>

        <button
          onClick={() => { setQcmStep(false); setError(''); setSelectedAnswer(null); }}
          className="w-full mt-2 text-texte-light text-xs py-2"
        >
          ← Retour au login
        </button>
      </div>
    );
  }

  // Login Step
  return (
    <div className="bg-blanc rounded-2xl p-6 border border-border">
      <div className="text-center mb-6">
        <span className="text-4xl">🏫</span>
        <h3 className="font-bold text-lg mt-2">Connexion EcoleDirecte</h3>
        <p className="text-xs text-texte-light mt-1">
          Utilisez vos identifiants parents ou eleve
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="text-xs font-semibold text-texte-light block mb-1">Identifiant</label>
          <input
            type="text"
            value={username}
            onChange={e => setUsername(e.target.value)}
            className="w-full bg-fond border border-border rounded-lg px-3 py-2.5 text-sm outline-none focus:border-accent"
            placeholder="Votre identifiant EcoleDirecte"
            autoComplete="username"
            required
          />
        </div>

        <div>
          <label className="text-xs font-semibold text-texte-light block mb-1">Mot de passe</label>
          <input
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            className="w-full bg-fond border border-border rounded-lg px-3 py-2.5 text-sm outline-none focus:border-accent"
            placeholder="Votre mot de passe"
            autoComplete="current-password"
            required
          />
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3">
            <p className="text-sm text-red-600">{error}</p>
          </div>
        )}

        <button
          type="submit"
          disabled={loading || !username || !password}
          className="w-full bg-accent text-white py-3 rounded-xl font-semibold text-sm disabled:opacity-50 transition-opacity"
        >
          {loading ? 'Connexion en cours...' : 'Se connecter'}
        </button>
      </form>

      {savedAccount && !savedAccount.sessionActive && (
        <p className="text-xs text-texte-light text-center mt-4">
          Derniere connexion : {savedAccount.studentName}
        </p>
      )}

      <div className="mt-4 p-3 bg-fond rounded-lg">
        <p className="text-xs text-texte-light text-center">
          Vos identifiants ne sont pas stockes. Seul un jeton de session temporaire est conserve.
        </p>
      </div>
    </div>
  );
}
