import { useState, useEffect, useCallback } from 'react';
import api from '../../api/client';
import { formatDate } from '../../utils/dateUtils';

export default function GradesView({ studentId }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [viewMode, setViewMode] = useState('recent'); // 'recent' or 'averages'
  const [selectedPeriod, setSelectedPeriod] = useState(null);

  const loadGrades = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await api.get(`/ecoledirecte/grades${studentId ? `?studentId=${studentId}` : ''}`);
      if (res.data.success) {
        setData(res.data);
      } else {
        setError(res.data.error || 'Erreur de chargement');
      }
    } catch (err) {
      if (err.response?.data?.error === 'SESSION_EXPIRED') {
        setError('Session expiree. Veuillez vous reconnecter.');
      } else {
        setError('Impossible de charger les notes');
      }
    } finally {
      setLoading(false);
    }
  }, [studentId]);

  useEffect(() => {
    loadGrades();
  }, [loadGrades]);

  function getGradeColor(grade, outOf) {
    const num = parseFloat(grade);
    const max = parseFloat(outOf) || 20;
    const ratio = num / max;
    if (ratio >= 0.75) return 'text-green-600 bg-green-50';
    if (ratio >= 0.5) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  }

  if (loading) {
    return (
      <div className="text-center py-8">
        <p className="text-2xl animate-bounce">📊</p>
        <p className="text-sm text-texte-light mt-2">Chargement des notes...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center">
        <p className="text-sm text-red-600">{error}</p>
        <button onClick={loadGrades} className="text-accent text-sm mt-2 font-semibold">
          Reessayer
        </button>
      </div>
    );
  }

  if (!data) return null;

  // Period selection
  const periods = data.periods || [];
  const currentPeriod = selectedPeriod
    ? periods.find(p => p.code === selectedPeriod)
    : (periods.find(p => !p.closed) || periods[periods.length - 1]);

  // Filter notes by selected period
  const filteredNotes = selectedPeriod
    ? (data.notes || []).filter(n => n.period === selectedPeriod)
    : (data.notes || []);

  return (
    <div className="space-y-4">
      {/* Period selector (trimestres) */}
      {periods.length > 1 && (
        <div className="flex gap-1 bg-blanc rounded-xl border border-border p-1">
          {periods.map(p => (
            <button
              key={p.code}
              onClick={() => setSelectedPeriod(p.code)}
              className={`flex-1 py-1.5 rounded-lg text-xs font-semibold transition-colors ${
                (selectedPeriod || currentPeriod?.code) === p.code
                  ? 'bg-warm text-white'
                  : 'text-texte-light'
              }`}
            >
              {p.label?.replace('Trimestre ', 'T') || p.code}
            </button>
          ))}
        </div>
      )}

      {/* General average */}
      {currentPeriod?.generalAvg && (
        <div className="bg-blanc rounded-2xl p-4 border border-border text-center">
          <p className="text-xs text-texte-light mb-1">{currentPeriod.label || 'Periode en cours'}</p>
          <p className="text-3xl font-bold text-accent">{currentPeriod.generalAvg}</p>
          <p className="text-xs text-texte-light mt-1">
            Moyenne de classe : {currentPeriod.classGeneralAvg || '-'}
          </p>
        </div>
      )}

      {/* Toggle */}
      <div className="flex bg-blanc rounded-xl border border-border p-1 gap-1">
        <button
          onClick={() => setViewMode('recent')}
          className={`flex-1 py-2 rounded-lg text-xs font-semibold ${
            viewMode === 'recent' ? 'bg-accent text-white' : 'text-texte-light'
          }`}
        >
          Dernieres notes
        </button>
        <button
          onClick={() => setViewMode('averages')}
          className={`flex-1 py-2 rounded-lg text-xs font-semibold ${
            viewMode === 'averages' ? 'bg-accent text-white' : 'text-texte-light'
          }`}
        >
          Moyennes
        </button>
      </div>

      {/* Recent grades */}
      {viewMode === 'recent' && (
        <div className="space-y-2">
          {filteredNotes.length === 0 ? (
            <div className="text-center py-6">
              <p className="text-sm text-texte-light">Aucune note disponible</p>
            </div>
          ) : (
            filteredNotes.slice(0, 30).map((note, i) => (
              <div key={i} className="bg-blanc rounded-xl p-4 border border-border">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <p className="font-semibold text-sm">{note.subject}</p>
                    {note.title && <p className="text-xs text-texte-light">{note.title}</p>}
                    {note.date && <p className="text-xs text-texte-light">{formatDate(note.date)}</p>}
                  </div>
                  <div className={`px-3 py-1.5 rounded-lg font-bold text-lg ${getGradeColor(note.grade, note.outOf)}`}>
                    {note.grade}<span className="text-xs font-normal">/{note.outOf}</span>
                  </div>
                </div>
                <div className="flex gap-3 mt-2 text-xs text-texte-light">
                  {note.classAvg && <span>Classe: {note.classAvg}</span>}
                  {note.classMin && <span>Min: {note.classMin}</span>}
                  {note.classMax && <span>Max: {note.classMax}</span>}
                  {note.coefficient !== '1' && <span>Coef: {note.coefficient}</span>}
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* Averages by subject */}
      {viewMode === 'averages' && currentPeriod?.averages && (
        <div className="space-y-2">
          {currentPeriod.averages.map((avg, i) => (
            <div key={i} className="bg-blanc rounded-xl p-3 border border-border flex items-center justify-between">
              <div className="flex-1">
                <p className="font-semibold text-sm">{avg.subject}</p>
                <div className="flex gap-2 text-xs text-texte-light mt-0.5">
                  <span>Classe: {avg.classAvg || '-'}</span>
                  {avg.coefficient && <span>Coef: {avg.coefficient}</span>}
                </div>
              </div>
              <div className={`px-3 py-1 rounded-lg font-bold ${getGradeColor(avg.studentAvg, 20)}`}>
                {avg.studentAvg || '-'}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
