import { useState, useEffect, useCallback } from 'react';
import api from '../../api/client';
import { getDayName, formatDate } from '../../utils/dateUtils';

function getMonday(d) {
  const date = new Date(d);
  const day = date.getDay();
  // If Saturday(6) or Sunday(0), go to NEXT Monday
  if (day === 0) {
    date.setDate(date.getDate() + 1);
  } else if (day === 6) {
    date.setDate(date.getDate() + 2);
  } else {
    date.setDate(date.getDate() - day + 1);
  }
  return date;
}

function getFriday(monday) {
  const d = new Date(monday);
  d.setDate(d.getDate() + 4);
  return d;
}

function toDateStr(d) {
  // Use local date to avoid timezone issues
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export default function TimetableView({ studentId }) {
  const [timetable, setTimetable] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [weekStart, setWeekStart] = useState(getMonday(new Date()));

  const loadTimetable = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const start = toDateStr(weekStart);
      const end = toDateStr(getFriday(weekStart));
      const res = await api.get(`/ecoledirecte/timetable?start=${start}&end=${end}${studentId ? `&studentId=${studentId}` : ''}`);
      if (res.data.success) {
        setTimetable(res.data.timetable);
      } else {
        setError(res.data.error || 'Erreur');
      }
    } catch (err) {
      if (err.response?.data?.error === 'SESSION_EXPIRED') {
        setError('Session expiree. Veuillez vous reconnecter.');
      } else {
        setError('Impossible de charger l\'emploi du temps');
      }
    } finally {
      setLoading(false);
    }
  }, [studentId, weekStart]);

  useEffect(() => {
    loadTimetable();
  }, [loadTimetable]);

  function changeWeek(delta) {
    const newStart = new Date(weekStart);
    newStart.setDate(newStart.getDate() + delta * 7);
    setWeekStart(newStart);
  }

  // Group timetable by day
  function groupByDay() {
    const days = {};
    for (let i = 0; i < 5; i++) {
      const d = new Date(weekStart);
      d.setDate(d.getDate() + i);
      const key = toDateStr(d);
      days[key] = [];
    }

    timetable.forEach(event => {
      const dateKey = event.start?.split(' ')?.[0] || event.start?.split('T')?.[0];
      if (dateKey && days[dateKey]) {
        days[dateKey].push(event);
      }
    });

    // Sort events by start time within each day
    Object.values(days).forEach(events => {
      events.sort((a, b) => (a.start || '').localeCompare(b.start || ''));
    });

    return days;
  }

  if (loading) {
    return (
      <div className="text-center py-8">
        <p className="text-2xl animate-bounce">🕐</p>
        <p className="text-sm text-texte-light mt-2">Chargement de l'emploi du temps...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-xl p-4 text-center">
        <p className="text-sm text-red-600">{error}</p>
        <button onClick={loadTimetable} className="text-accent text-sm mt-2 font-semibold">
          Reessayer
        </button>
      </div>
    );
  }

  const days = groupByDay();

  return (
    <div className="space-y-4">
      {/* Week navigation */}
      <div className="flex items-center justify-between bg-blanc rounded-xl p-3 border border-border">
        <button onClick={() => changeWeek(-1)} className="text-accent font-bold px-2">←</button>
        <span className="font-semibold text-sm">
          {formatDate(toDateStr(weekStart))} - {formatDate(toDateStr(getFriday(weekStart)))}
        </span>
        <button onClick={() => changeWeek(1)} className="text-accent font-bold px-2">→</button>
      </div>

      {/* Days */}
      {Object.entries(days).map(([date, events]) => {
        const d = new Date(date);
        const isToday = toDateStr(new Date()) === date;

        return (
          <div key={date}>
            <h3 className={`font-semibold text-sm mb-2 ${isToday ? 'text-accent' : 'text-texte-light'}`}>
              {isToday && '● '}{getDayName(d.getDay(), true)} {formatDate(date)}
            </h3>
            {events.length === 0 ? (
              <div className="bg-blanc rounded-xl p-3 border border-border">
                <p className="text-xs text-texte-light text-center">Pas de cours</p>
              </div>
            ) : (
              <div className="space-y-1.5">
                {events.map((event, i) => {
                  const startTime = (event.start || '').split(' ')[1]?.slice(0, 5) || (event.start || '').split('T')[1]?.slice(0, 5) || '';
                  const endTime = (event.end || '').split(' ')[1]?.slice(0, 5) || (event.end || '').split('T')[1]?.slice(0, 5) || '';

                  return (
                    <div
                      key={i}
                      className={`bg-blanc rounded-xl p-3 border-l-4 border border-border ${
                        event.cancelled ? 'opacity-50 line-through' : ''
                      }`}
                      style={{ borderLeftColor: event.color || '#7C9082' }}
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <p className="font-semibold text-sm">
                            {event.text || event.subject}
                            {event.cancelled && ' (Annule)'}
                            {event.modified && ' ✱'}
                          </p>
                          <div className="flex gap-3 text-xs text-texte-light mt-0.5">
                            {event.teacher && <span>👤 {event.teacher}</span>}
                            {event.room && <span>📍 {event.room}</span>}
                          </div>
                        </div>
                        <div className="text-right text-xs text-texte-light shrink-0 ml-2">
                          <p className="font-semibold text-texte">{startTime}</p>
                          <p>{endTime}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
