import { useState, useEffect, useRef, useCallback } from 'react';
import { useFamily } from '../../context/FamilyContext';
import api from '../../api/client';
import Avatar from '../common/Avatar';

// Persist quiz progress so navigating away doesn't lose state
function getQuizProgress() {
  try {
    const raw = sessionStorage.getItem('ff_quiz_progress');
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function saveQuizProgress(data) {
  try {
    if (data) sessionStorage.setItem('ff_quiz_progress', JSON.stringify(data));
    else sessionStorage.removeItem('ff_quiz_progress');
  } catch {}
}

export default function QuizPage() {
  const { members, currentMember, setCurrentMember } = useFamily();
  const saved = getQuizProgress();
  const [quiz, setQuiz] = useState(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [currentQ, setCurrentQ] = useState(saved?.currentQ || 0);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [result, setResult] = useState(null);
  const [scores, setScores] = useState([]);
  const [showResults, setShowResults] = useState(saved?.showResults || false);
  const resultRef = useRef(null);

  // Persist quiz progress on change
  useEffect(() => {
    if (quiz) {
      saveQuizProgress({ currentQ, showResults });
    }
  }, [currentQ, showResults, quiz]);

  const loadQuiz = useCallback(async () => {
    setLoading(true);
    try {
      const res = await api.get('/quiz/today');
      const q = res.data.quiz;
      setQuiz(q);
      // If resuming, find where the child left off (skip already-answered questions)
      if (q && currentMember) {
        const questions = q.questions?.filter(qq =>
          qq.target_member === currentMember.id || !qq.target_member
        ) || [];
        const firstUnanswered = questions.findIndex(qq =>
          !qq.answered?.some(a => a.member_id === currentMember.id)
        );
        if (firstUnanswered > 0) setCurrentQ(firstUnanswered);
        if (firstUnanswered === -1 && questions.length > 0) setShowResults(true);
      }
    } catch {}
    setLoading(false);
  }, [currentMember]);

  const loadScores = useCallback(async () => {
    try {
      const params = currentMember ? { memberId: currentMember.id } : {};
      const res = await api.get('/quiz/scores', { params });
      setScores(res.data.scores);
    } catch {}
  }, [currentMember]);

  useEffect(() => {
    loadQuiz();
    loadScores();
  }, [loadQuiz, loadScores]);

  async function generateQuiz(force) {
    setGenerating(true);
    try {
      await api.post('/quiz/generate', { forceRegenerate: force === true });
      await loadQuiz();
      setCurrentQ(0);
      setSelectedAnswer(null);
      setResult(null);
      setShowResults(false);
      saveQuizProgress(null);
    } catch (e) {
      console.error(e);
    } finally {
      setGenerating(false);
    }
  }

  async function submitAnswer(answerIdx) {
    if (!currentMember || selectedAnswer !== null) return;
    setSelectedAnswer(answerIdx);

    const question = filteredQuestions[currentQ];
    try {
      const res = await api.post('/quiz/answer', {
        questionId: question.id,
        memberId: currentMember.id,
        answer: answerIdx,
      });
      setResult(res.data);
      loadScores();
      // Scroll to result after a short delay
      setTimeout(() => {
        document.documentElement.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'instant' });
      }, 300);
    } catch {}
  }

  function nextQuestion() {
    setSelectedAnswer(null);
    setResult(null);
    if (currentQ < filteredQuestions.length - 1) {
      setCurrentQ(currentQ + 1);
    } else {
      setShowResults(true);
    }
  }

  function goBack() {
    setCurrentMember(null);
    setCurrentQ(0);
    setSelectedAnswer(null);
    setResult(null);
    setShowResults(false);
    saveQuizProgress(null);
  }

  // Filter questions based on role:
  // - Parents (Maman/Papa): see ALL questions (they supervise the quiz)
  // - Children: see only their targeted questions + family questions
  const isParent = currentMember?.role === 'parent';
  const filteredQuestions = isParent
    ? (quiz?.questions || [])
    : (quiz?.questions?.filter(q =>
        q.target_member === currentMember?.id || !q.target_member
      ) || []);

  // Score board — filtered to current child
  if (showResults) {
    // Compute this child's answers from today's quiz
    const myAnswers = filteredQuestions.map(q => {
      const myAnswer = q.answered?.find(a => a.member_id === currentMember?.id);
      return { question: q, answer: myAnswer };
    });
    const correctCount = myAnswers.filter(a => a.answer?.is_correct).length;
    const totalCount = myAnswers.length;
    const pct = totalCount > 0 ? Math.round((correctCount / totalCount) * 100) : 0;
    const emoji = pct >= 80 ? '🏆' : pct >= 60 ? '⭐' : pct >= 40 ? '💪' : '🌱';
    const myStreak = scores.find(s => s.member_id === currentMember?.id);

    return (
      <div className="space-y-4">
        <button onClick={goBack} className="text-accent text-sm">← Retour</button>

        {/* Score card */}
        <div className={`rounded-2xl p-5 text-center border ${pct >= 60 ? 'bg-green-50 dark:bg-emerald-900/30 border-green-200 dark:border-emerald-700/50' : 'bg-amber-50 dark:bg-amber-900/30 border-amber-200 dark:border-amber-700/50'}`}>
          <p className="text-4xl mb-1">{emoji}</p>
          <p className="text-2xl font-bold text-gray-800 dark:text-slate-100">{correctCount}/{totalCount}</p>
          <p className="text-sm text-gray-600 dark:text-slate-300 mt-1">
            {pct >= 80 ? 'Excellent !' : pct >= 60 ? 'Bien joué !' : pct >= 40 ? 'Pas mal, continue !' : 'Tu feras mieux demain !'}
          </p>
          {myStreak && (
            <p className="text-xs text-gray-500 dark:text-slate-400 mt-2">
              🔥 Streak : {myStreak.current_streak} jour{myStreak.current_streak > 1 ? 's' : ''}
              {myStreak.best_streak > 1 && ` · Record : ${myStreak.best_streak}`}
            </p>
          )}
        </div>

        {/* Answer recap */}
        <div className="space-y-2">
          <h3 className="text-sm font-semibold text-texte-light dark:text-slate-400">Tes réponses</h3>
          {myAnswers.map((a, i) => {
            const q = a.question;
            const isCorrect = a.answer?.is_correct;
            const answered = a.answer != null;
            return (
              <div key={i} className={`bg-blanc dark:bg-slate-900 rounded-xl p-3 border ${isCorrect ? 'border-green-200 dark:border-emerald-700/50' : answered ? 'border-red-200 dark:border-red-700/50' : 'border-gray-100 dark:border-slate-700'}`}>
                <div className="flex items-start gap-2">
                  <span className="text-sm mt-0.5">{isCorrect ? '✅' : answered ? '❌' : '⬜'}</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-800 dark:text-slate-100">{q.question_text || q.question}</p>
                    {answered && !isCorrect && q.correct_answer != null && (
                      <p className="text-xs text-green-600 dark:text-emerald-400 mt-1">Réponse : {q.choices?.[q.correct_answer] || q.correct_answer}</p>
                    )}
                    {q.explanation && answered && !isCorrect && (
                      <p className="text-xs text-gray-500 dark:text-slate-400 mt-0.5">{q.explanation}</p>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className="flex gap-2">
          <button onClick={() => generateQuiz(true)} disabled={generating}
            className="flex-1 bg-accent text-white py-3 rounded-xl font-semibold text-sm active:scale-[0.98] disabled:opacity-50">
            {generating ? '🤖 Génération...' : '🔄 Nouveau Quiz'}
          </button>
          <button onClick={goBack}
            className="flex-1 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 text-gray-700 dark:text-slate-200 py-3 rounded-xl font-semibold text-sm active:scale-[0.98]">
            Retour
          </button>
        </div>
      </div>
    );
  }

  // Member selector
  if (!currentMember) {
    return (
      <div className="space-y-4">
        <h2 className="text-xl font-bold">Defi du Soir 🎮</h2>
        <p className="text-sm text-texte-light dark:text-slate-400">Qui joue ce soir ?</p>
        <div className="space-y-3">
          {members.map(m => (
            <button
              key={m.id}
              onClick={() => { setCurrentMember(m); setCurrentQ(0); setShowResults(false); }}
              className="w-full bg-blanc dark:bg-slate-900 rounded-xl p-4 border border-border dark:border-slate-700 flex items-center gap-3 hover:shadow-md transition-shadow"
            >
              <Avatar name={m.name} color={m.avatar_color} size="lg" />
              <span className="font-semibold">{m.name}</span>
              {scores.find(s => s.member_id === m.id) && (
                <span className="ml-auto text-sm text-warm">
                  🔥 {scores.find(s => s.member_id === m.id).current_streak}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="text-center py-12">
        <p className="text-3xl animate-spin">🤖</p>
        <p className="text-sm text-texte-light dark:text-slate-400 mt-2">Chargement...</p>
      </div>
    );
  }

  // No quiz yet - generate
  if (!quiz) {
    return (
      <div className="text-center py-12 space-y-4">
        <button onClick={goBack} className="text-accent text-sm">← Retour</button>
        <p className="text-5xl">🎮</p>
        <h2 className="text-xl font-bold">Defi du Soir</h2>
        <p className="text-sm text-texte-light dark:text-slate-400">
          Pas encore de quiz ! Foxie va preparer des questions basees sur tes devoirs.
        </p>
        <button
          onClick={() => generateQuiz()}
          disabled={generating}
          className="bg-accent text-white px-6 py-3 rounded-xl font-semibold text-sm disabled:opacity-50"
        >
          {generating ? 'Foxie prepare le quiz... 🤖' : 'Lancer le Defi !'}
        </button>
      </div>
    );
  }

  // Quiz loaded but no questions for this player
  const question = filteredQuestions[currentQ];
  if (!question || filteredQuestions.length === 0) {
    return (
      <div className="text-center py-12 space-y-4">
        <button onClick={goBack} className="text-accent text-sm">← Retour</button>
        <p className="text-5xl">🎮</p>
        <h2 className="text-xl font-bold">Pas de questions pour toi</h2>
        <p className="text-sm text-texte-light dark:text-slate-400">Regenere le quiz pour avoir de nouvelles questions !</p>
        <button
          onClick={() => generateQuiz(true)}
          disabled={generating}
          className="bg-accent text-white px-6 py-3 rounded-xl font-semibold text-sm disabled:opacity-50"
        >
          {generating ? 'Generation... 🤖' : 'Regenerer le Quiz'}
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with back button */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <button onClick={goBack} className="text-accent text-sm mr-1">←</button>
          <Avatar name={currentMember.name} color={currentMember.avatar_color} size="sm" />
          <span className="font-semibold text-sm">{currentMember.name}</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-sm text-texte-light dark:text-slate-400">
            {currentQ + 1} / {filteredQuestions.length}
          </span>
          <button
            onClick={() => { if (window.confirm('Regenerer un nouveau quiz ?')) generateQuiz(true); }}
            className="text-xs text-texte-light dark:text-slate-400 hover:text-accent"
          >
            🔄
          </button>
        </div>
      </div>

      {/* Progress bar */}
      <div className="w-full bg-accent-light rounded-full h-2">
        <div
          className="bg-accent h-2 rounded-full transition-all"
          style={{ width: `${((currentQ + 1) / filteredQuestions.length) * 100}%` }}
        />
      </div>

      {/* Subject badge */}
      <div className="flex items-center gap-2 flex-wrap">
        {question.subject && (
          <span className="text-xs bg-accent-light text-accent px-2 py-0.5 rounded-full font-medium">
            {question.subject}
          </span>
        )}
        {question.difficulty && (
          <span className={`px-2 py-0.5 rounded-full text-xs ${
            question.difficulty === 'easy' ? 'bg-green-100 text-green-700' :
            question.difficulty === 'medium' ? 'bg-yellow-100 text-yellow-700' :
            'bg-red-100 text-red-700'
          }`}>
            {question.difficulty === 'easy' ? 'Facile' : question.difficulty === 'medium' ? 'Moyen' : 'Difficile'}
          </span>
        )}
      </div>

      {/* Question */}
      <div className="bg-blanc dark:bg-slate-900 rounded-2xl p-5 border border-border dark:border-slate-700">
        <p className="font-semibold text-base leading-relaxed">{question.question_text}</p>
      </div>

      {/* Choices */}
      <div className="space-y-2">
        {question.choices.map((choice, idx) => {
          let className = 'w-full text-left bg-blanc border rounded-xl p-4 text-sm transition-all ';
          if (selectedAnswer !== null) {
            if (idx === question.correct_answer) {
              className += 'border-green-500 bg-green-50 font-semibold';
            } else if (idx === selectedAnswer && !result?.isCorrect) {
              className += 'border-red-500 bg-red-50';
            } else {
              className += 'border-border dark:border-slate-700 opacity-50';
            }
          } else {
            className += 'border-border dark:border-slate-700 hover:border-accent hover:shadow-sm active:scale-[0.98]';
          }

          return (
            <button
              key={idx}
              onClick={() => submitAnswer(idx)}
              disabled={selectedAnswer !== null}
              className={className}
            >
              <span className="inline-block w-6 h-6 rounded-full bg-accent-light text-accent text-xs font-bold leading-6 text-center mr-3">
                {String.fromCharCode(65 + idx)}
              </span>
              {choice}
            </button>
          );
        })}
      </div>

      {/* Result feedback */}
      {result && (
        <div className={`rounded-xl p-4 mb-6 ${result.isCorrect ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'}`}>
          <p className="font-semibold text-sm">
            {result.isCorrect ? 'Bravo ! 🎉' : 'Pas tout a fait... 😊'}
          </p>
          {result.explanation && (
            <p className="text-xs mt-1 text-texte-light dark:text-slate-400">{result.explanation}</p>
          )}
          <button
            ref={resultRef}
            onClick={nextQuestion}
            className="mt-3 bg-accent text-white px-4 py-2 rounded-lg text-sm font-semibold"
          >
            {currentQ < filteredQuestions.length - 1 ? 'Question suivante →' : 'Voir les resultats'}
          </button>
        </div>
      )}
    </div>
  );
}
