import { useState, useEffect, useRef, useCallback } from 'react';
import { useFamily } from '../context/FamilyContext';
import api from '../api/client';

const CHECK_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
const SW_PATH = '/sw-notifications.js';

export function useNotifications() {
  const { currentMember } = useFamily();
  const [permissionGranted, setPermissionGranted] = useState(false);
  const [preferences, setPreferences] = useState(null);
  const swRef = useRef(null);
  const intervalRef = useRef(null);

  // Check current permission state
  useEffect(() => {
    try {
      if ('Notification' in window) {
        setPermissionGranted(Notification.permission === 'granted');
      }
    } catch {}
  }, []);

  // Register service worker
  useEffect(() => {
    if (!('serviceWorker' in navigator)) return;

    navigator.serviceWorker.register(SW_PATH)
      .then(reg => { swRef.current = reg; })
      .catch(() => { /* SW not supported or failed */ });

    return () => { /* SW stays registered */ };
  }, []);

  // Request permission
  const requestPermission = useCallback(async () => {
    try {
      if (!('Notification' in window)) return false;
      const result = await Notification.requestPermission();
      const granted = result === 'granted';
      setPermissionGranted(granted);
      return granted;
    } catch {
      return false;
    }
  }, []);

  // Show a notification via the service worker
  const showNotification = useCallback((title, body, tag, url) => {
    try {
      if (swRef.current?.active) {
        swRef.current.active.postMessage({
          type: 'SHOW_NOTIFICATION',
          title, body, tag, url,
        });
      } else if ('Notification' in window && Notification.permission === 'granted') {
        // Fallback: direct notification (no click handling)
        new Notification(title, { body, tag, icon: '/logo192.png' });
      }
    } catch {}
  }, []);

  // Load preferences
  const loadPreferences = useCallback(async (memberId) => {
    try {
      const res = await api.get(`/notifications/preferences/${memberId}`);
      if (res.data.success) setPreferences(res.data.preferences);
    } catch {}
  }, []);

  // Update preferences
  const updatePreferences = useCallback(async (memberId, prefs) => {
    try {
      await api.put(`/notifications/preferences/${memberId}`, prefs);
      setPreferences(prev => ({ ...prev, ...prefs }));
    } catch {}
  }, []);

  // Check for reminders and show them
  const checkReminders = useCallback(async () => {
    if (!currentMember?.id) return;
    if (!('Notification' in window) || Notification.permission !== 'granted') return;

    try {
      const res = await api.get(`/notifications/reminders/${currentMember.id}`);
      if (!res.data.success) return;

      for (const reminder of res.data.reminders) {
        showNotification(reminder.title, reminder.body, reminder.tag, reminder.url);
        // Log as shown
        try {
          await api.post('/notifications/shown', {
            memberId: currentMember.id,
            type: reminder.type,
            title: reminder.title,
            body: reminder.body,
          });
        } catch {}
      }
    } catch {}
  }, [currentMember?.id, showNotification]);

  // Set up interval for checking reminders
  useEffect(() => {
    if (!currentMember?.id) return;

    // Load prefs
    loadPreferences(currentMember.id);

    // Initial check after 10 seconds (let app settle)
    const timeout = setTimeout(checkReminders, 10000);

    // Periodic checks
    intervalRef.current = setInterval(checkReminders, CHECK_INTERVAL_MS);

    return () => {
      clearTimeout(timeout);
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [currentMember?.id, checkReminders, loadPreferences]);

  return {
    permissionGranted,
    requestPermission,
    preferences,
    updatePreferences,
    showNotification,
    loadPreferences,
  };
}
