import { useState, useEffect } from 'react';
import { useFamily } from '../../context/FamilyContext';
import api from '../../api/client';
import Avatar from '../common/Avatar';
import MindMapMarkmap from '../common/MindMapMarkmap';
import { formatDate } from '../../utils/dateUtils';

function MindMapViewer({ mapData, onClose }) {
  if (!mapData) return null;
  const title = mapData.central_topic || mapData.central || mapData.title || 'Carte mentale';
  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex flex-col" onClick={onClose}>
      <div className="flex-1 overflow-auto p-4" onClick={e => e.stopPropagation()}>
        <div className="bg-blanc dark:bg-slate-900 rounded-2xl p-5 max-w-lg mx-auto">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-medium text-lg">{title}</h3>
            <button onClick={onClose} className="text-texte-light dark:text-slate-400 text-xl px-2">✕</button>
          </div>
          <MindMapMarkmap data={mapData} height={420} />
          <button onClick={onClose}
            className="mt-4 w-full bg-accent text-white py-2.5 rounded-xl text-sm">
            Fermer
          </button>
        </div>
      </div>
    </div>
  );
}

function qualityStyles(level) {
  if (level === 'solide') return 'bg-green-50 text-green-700 border-green-200';
  if (level === 'partiel') return 'bg-amber-50 text-amber-700 border-amber-200';
  return 'bg-slate-50 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
}

function ReportEvidence({ items }) {
  if (!items?.length) {
    return (
      <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-3 border border-slate-200 dark:border-slate-700">
        <p className="text-xs font-medium text-slate-600 dark:text-slate-300 mb-1">Preuves utilisées</p>
        <p className="text-sm text-slate-500 dark:text-slate-400">
          Pas encore assez de traces de travail cette semaine. Quelques échanges avec Foxie rendront ce bilan beaucoup plus personnalisé.
        </p>
      </div>
    );
  }

  return (
    <div>
      <p className="text-xs font-medium text-texte-light dark:text-slate-400 mb-2">Preuves utilisées</p>
      <div className="space-y-2">
        {items.slice(0, 6).map((item, i) => (
          <div key={i} className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2.5 border border-slate-200 dark:border-slate-700">
            <div className="flex items-start justify-between gap-2">
              <p className="text-sm font-medium text-texte dark:text-slate-100">{item.title}</p>
              {item.dateLabel && <span className="text-[11px] text-slate-400 shrink-0">{item.dateLabel}</span>}
            </div>
            {item.detail && <p className="text-xs text-slate-600 dark:text-slate-400 mt-0.5 leading-relaxed">{item.detail}</p>}
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function BilanPage() {
  const { childMembers } = useFamily();
  const [selectedChild, setSelectedChild] = useState(null);
  const [mindmaps, setMindmaps] = useState([]);
  const [grades, setGrades] = useState([]);
  const [reviews, setReviews] = useState({ due: 0 });
  const [parentReport, setParentReport] = useState(null);
  const [reportLoading, setReportLoading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [viewingMindmap, setViewingMindmap] = useState(null);

  useEffect(() => {
    if (selectedChild) loadBilan(selectedChild.id);
  }, [selectedChild]);

  async function loadBilan(memberId) {
    setLoading(true);
    try {
      const [mmRes, gradesRes, reviewsRes] = await Promise.allSettled([
        api.get(`/kb/mindmaps/${memberId}`),
        api.get(`/kb/grades/${memberId}`),
        api.get(`/kb/reviews/due/${memberId}`),
      ]);
      setMindmaps(mmRes.status === 'fulfilled' ? mmRes.value.data.mindmaps || [] : []);
      setGrades(gradesRes.status === 'fulfilled' ? gradesRes.value.data.grades || [] : []);
      const dueTopics = reviewsRes.status === 'fulfilled' ? reviewsRes.value.data.topics || [] : [];
      setReviews({ due: dueTopics.length });
      try {
        const reportRes = await api.get(`/parent/report/${memberId}`);
        setParentReport(reportRes.data.report || null);
      } catch {
        setParentReport(null);
      }
    } catch {}
    setLoading(false);
  }

  async function generateParentReport() {
    if (!selectedChild || reportLoading) return;
    setReportLoading(true);
    try {
      const res = await api.post(`/parent/report/${selectedChild.id}`);
      if (res.data.success) setParentReport(res.data.report);
    } catch {}
    setReportLoading(false);
  }

  async function openMindmap(mm) {
    try {
      const res = await api.get(`/kb/mindmap/${mm.id}`);
      setViewingMindmap(res.data.mindmap.map_data);
    } catch {}
  }

  // Group mindmaps by subject
  const bySubject = mindmaps.reduce((acc, mm) => {
    const key = mm.subject || 'Divers';
    if (!acc[key]) acc[key] = [];
    acc[key].push(mm);
    return acc;
  }, {});

  // ─── Child selector ───────────────────────────────────────────────────────
  if (!selectedChild) {
    return (
      <div className="space-y-4">
        <div>
          <h2 className="text-xl font-medium">Bilan annuel</h2>
          <p className="text-sm text-texte-light dark:text-slate-400">Toutes les cartes mentales pour réviser l'année</p>
        </div>

        <div className="bg-accent-light dark:bg-accent/20 rounded-xl p-4 border border-border dark:border-slate-700 text-sm space-y-2">
          <p className="font-medium">À quoi ça sert ?</p>
          <ul className="text-xs text-texte-light dark:text-slate-400 space-y-1">
            <li>🗺️ <strong>Cartes mentales</strong> — résumés visuels de chaque chapitre</li>
            <li>📊 <strong>Notes par matière</strong> — repérer les points faibles</li>
            <li>🔁 <strong>Révisions espacées</strong> — méthode 2-3-5-7 pour tout retenir</li>
            <li>🏆 <strong>Bilan trimestriel</strong> — préparer les conseils de classe</li>
          </ul>
        </div>

        <div className="space-y-3">
          {childMembers.map(child => (
            <button key={child.id} onClick={() => setSelectedChild(child)}
              className="w-full bg-blanc dark:bg-slate-900 rounded-xl p-4 border border-border dark:border-slate-700 flex items-center gap-4 hover:shadow-md transition-shadow active:scale-[0.98]">
              <Avatar name={child.name} color={child.avatar_color} size="lg" />
              <div className="text-left flex-1">
                <h3 className="font-medium text-lg">{child.name}</h3>
                <p className="text-sm text-texte-light dark:text-slate-400">{child.grade} — {child.age} ans</p>
              </div>
              <span className="text-xl">🎓</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // ─── Bilan detail ─────────────────────────────────────────────────────────
  const validGrades = grades.filter(g => Number.isFinite(g.student_avg) && g.student_avg >= 0 && g.student_avg <= 20);
  const anomalousGrades = grades.filter(g => !Number.isFinite(g.student_avg) || g.student_avg < 0 || g.student_avg > 20);
  const weakGrades = validGrades.filter(g => g.student_avg < 10 || (g.class_avg && g.student_avg < g.class_avg - 2));
  const strongGrades = validGrades.filter(g => g.student_avg >= 14);

  return (
    <div className="space-y-5">
      {viewingMindmap && <MindMapViewer mapData={viewingMindmap} onClose={() => setViewingMindmap(null)} />}

      <div className="flex items-center gap-2">
        <button onClick={() => setSelectedChild(null)} className="text-accent text-sm">← Retour</button>
      </div>

      <div className="flex items-center gap-3">
        <Avatar name={selectedChild.name} color={selectedChild.avatar_color} size="lg" />
        <div>
          <h2 className="font-medium text-xl">{selectedChild.name}</h2>
          <p className="text-sm text-texte-light dark:text-slate-400">{selectedChild.grade} — Bilan annuel</p>
        </div>
      </div>

      {loading ? (
        <div className="text-center py-8">
          <p className="text-2xl animate-bounce">📚</p>
          <p className="text-sm text-texte-light dark:text-slate-400 mt-2">Chargement du bilan...</p>
        </div>
      ) : (
        <>
          {/* Stats overview */}
          <div className="grid grid-cols-3 gap-2">
            <div className="bg-blanc dark:bg-slate-900 rounded-xl p-3 border border-border dark:border-slate-700 text-center">
              <p className="text-2xl font-medium text-accent">{mindmaps.length}</p>
              <p className="text-xs text-texte-light dark:text-slate-400">Cartes mentales</p>
            </div>
            <div className={`rounded-xl p-3 border text-center ${weakGrades.length > 0 ? 'bg-orange-50 border-orange-200' : 'bg-green-50 border-green-200'}`}>
              <p className={`text-2xl font-medium ${weakGrades.length > 0 ? 'text-orange-600' : 'text-green-600'}`}>
                {weakGrades.length > 0 ? weakGrades.length : '✓'}
              </p>
              <p className={`text-xs ${weakGrades.length > 0 ? 'text-orange-600' : 'text-green-600'}`}>
                {weakGrades.length > 0 ? 'À renforcer' : 'Notes OK'}
              </p>
            </div>
            <div className="bg-blanc dark:bg-slate-900 rounded-xl p-3 border border-border dark:border-slate-700 text-center">
              <p className="text-2xl font-medium text-accent">{reviews.due}</p>
              <p className="text-xs text-texte-light dark:text-slate-400">À réviser ce soir</p>
            </div>
          </div>

          {/* Foxie weekly parent report */}
          <div className="bg-blanc dark:bg-slate-900 rounded-xl p-4 border border-border dark:border-slate-700 space-y-3">
            <div className="flex items-center justify-between gap-3">
              <div>
                <h3 className="font-medium text-base">Bilan Foxie de la semaine</h3>
                <p className="text-xs text-texte-light dark:text-slate-400">Ce que Foxie a compris et quoi faire maintenant</p>
              </div>
              <button
                onClick={generateParentReport}
                disabled={reportLoading}
                className="bg-accent text-white px-3 py-2 rounded-xl text-xs disabled:opacity-50 active:scale-[0.98]"
              >
                {reportLoading ? 'Analyse...' : parentReport ? 'Rafraîchir' : 'Générer'}
              </button>
            </div>

            {parentReport ? (
              <div className="space-y-3">
                {parentReport.resume && (
                  <p className="text-sm leading-relaxed text-texte">{parentReport.resume}</p>
                )}

                {parentReport.dataQuality && (
                  <div className={`rounded-lg p-3 border ${qualityStyles(parentReport.dataQuality.level)}`}>
                    <div className="flex items-start justify-between gap-3">
                      <div>
                        <p className="text-xs font-medium">{parentReport.dataQuality.label}</p>
                        <p className="text-xs mt-1 opacity-90">{parentReport.dataQuality.detail}</p>
                      </div>
                    </div>
                  </div>
                )}

                {parentReport.metrics && (
                  <div className="grid grid-cols-3 gap-2">
                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 border border-slate-200 dark:border-slate-700 text-center">
                      <p className="text-lg font-medium text-accent">{parentReport.metrics.messages || 0}</p>
                      <p className="text-[11px] text-texte-light dark:text-slate-400">messages</p>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 border border-slate-200 dark:border-slate-700 text-center">
                      <p className="text-lg font-medium text-accent">{parentReport.metrics.observations || 0}</p>
                      <p className="text-[11px] text-texte-light dark:text-slate-400">observations</p>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-800 rounded-lg p-2 border border-slate-200 dark:border-slate-700 text-center">
                      <p className="text-lg font-medium text-accent">{parentReport.metrics.quizAnswers || 0}</p>
                      <p className="text-[11px] text-texte-light dark:text-slate-400">quiz</p>
                    </div>
                  </div>
                )}

                <ReportEvidence items={parentReport.preuves} />

                {parentReport.progres?.length > 0 && (
                  <div>
                    <p className="text-xs font-medium text-green-700 mb-1">Progrès observés</p>
                    <div className="space-y-1">
                      {parentReport.progres.map((item, i) => (
                        <p key={i} className="text-sm text-texte-light dark:text-slate-400">• {item}</p>
                      ))}
                    </div>
                  </div>
                )}

                {parentReport.attention?.length > 0 && (
                  <div>
                    <p className="text-xs font-medium text-orange-700 mb-1">À surveiller</p>
                    <div className="space-y-2">
                      {parentReport.attention.map((item, i) => (
                        <div key={i} className="bg-orange-50 border border-orange-100 rounded-lg p-2">
                          <p className="text-sm font-medium text-orange-800">{item.sujet}</p>
                          <p className="text-xs text-orange-700">{item.probleme}</p>
                          {item.cause && <p className="text-xs text-orange-500 mt-0.5">Cause probable : {item.cause}</p>}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {parentReport.conseil && (
                  <div className="bg-accent-light dark:bg-accent/20 rounded-lg p-3 border border-border dark:border-slate-700">
                    <p className="text-xs font-medium text-accent mb-1">Action parent</p>
                    <p className="text-sm text-texte">{parentReport.conseil}</p>
                  </div>
                )}

                {parentReport.previsions && (
                  <div>
                    <p className="text-xs font-medium text-texte-light dark:text-slate-400 mb-1">À suivre</p>
                    <p className="text-sm text-texte-light dark:text-slate-400 leading-relaxed">{parentReport.previsions}</p>
                  </div>
                )}
              </div>
            ) : (
              <p className="text-sm text-texte-light dark:text-slate-400">
                Génère un bilan après quelques échanges avec Foxie. Il résumera les progrès, les difficultés et une action simple à faire à la maison.
              </p>
            )}
          </div>

          {/* Weak subjects alert */}
          {weakGrades.length > 0 && (
            <div className="bg-orange-50 rounded-xl p-4 border border-orange-200">
              <p className="font-medium text-sm text-orange-800 mb-2">Matières à renforcer</p>
              <div className="space-y-1">
                {weakGrades.map((g, i) => (
                  <div key={i} className="flex items-center justify-between">
                    <span className="text-sm text-orange-700">{g.subject}</span>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-medium text-orange-700">{g.student_avg}/20</span>
                      {g.class_avg && <span className="text-xs text-orange-400">(classe: {g.class_avg})</span>}
                    </div>
                  </div>
                ))}
              </div>
              <p className="text-xs text-orange-600 mt-2">
                💡 Génère des cartes mentales sur ces matières pour renforcer !
              </p>
            </div>
          )}

          {/* Strong subjects */}
          {strongGrades.length > 0 && (
            <div className="bg-green-50 rounded-xl p-3 border border-green-200">
              <p className="text-xs font-medium text-green-700 mb-1">Points forts</p>
              <div className="flex flex-wrap gap-1.5">
                {strongGrades.map((g, i) => (
                  <span key={i} className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-medium">
                    {g.subject} — {g.student_avg}/20
                  </span>
                ))}
              </div>
            </div>
          )}

          {anomalousGrades.length > 0 && (
            <div className="bg-slate-50 dark:bg-slate-800 rounded-xl p-3 border border-slate-200 dark:border-slate-700">
              <p className="text-xs font-medium text-slate-600 dark:text-slate-300 mb-1">Données scolaires à vérifier</p>
              <p className="text-xs text-slate-500 dark:text-slate-400">
                {anomalousGrades.length} valeur{anomalousGrades.length > 1 ? 's' : ''} hors barème masquée{anomalousGrades.length > 1 ? 's' : ''} du bilan pour éviter une conclusion faussée.
              </p>
            </div>
          )}

          {/* Mind maps by subject */}
          <div>
            <h3 className="font-medium text-sm text-texte-light dark:text-slate-400 mb-3">
              Cartes mentales ({mindmaps.length})
            </h3>

            {mindmaps.length === 0 ? (
              <div className="bg-blanc dark:bg-slate-900 rounded-xl p-6 border border-border dark:border-slate-700 text-center space-y-2">
                <p className="text-2xl">🗺️</p>
                <p className="text-sm text-texte-light dark:text-slate-400">Aucune carte mentale encore.</p>
                <p className="text-xs text-texte-light dark:text-slate-400">
                  Les cartes se créeront automatiquement après quelques échanges avec Foxie.
                </p>
              </div>
            ) : (
              Object.entries(bySubject).map(([subject, maps]) => (
                <div key={subject} className="mb-4">
                  <p className="text-xs font-medium text-texte-light dark:text-slate-400 uppercase tracking-wide mb-2">{subject}</p>
                  <div className="space-y-2">
                    {maps.map(mm => (
                      <button
                        key={mm.id}
                        onClick={() => openMindmap(mm)}
                        className="w-full bg-blanc dark:bg-slate-900 rounded-xl p-3.5 border border-border dark:border-slate-700 text-left hover:shadow-sm active:scale-[0.98] flex items-center justify-between"
                      >
                        <div>
                          <p className="font-medium text-sm">{mm.topic}</p>
                          <p className="text-xs text-texte-light dark:text-slate-400 mt-0.5">Mise à jour {formatDate(mm.updated_at)}</p>
                        </div>
                        <span className="text-accent text-lg">🗺️</span>
                      </button>
                    ))}
                  </div>
                </div>
              ))
            )}
          </div>

          {/* All grades table */}
          {validGrades.length > 0 && (
            <div>
              <h3 className="font-medium text-sm text-texte-light dark:text-slate-400 mb-3">Toutes les notes</h3>
              <div className="bg-blanc dark:bg-slate-900 rounded-xl border border-border dark:border-slate-700 overflow-hidden">
                {validGrades.sort((a, b) => a.student_avg - b.student_avg).map((g, i) => {
                  const isWeak = g.student_avg < 10 || (g.class_avg && g.student_avg < g.class_avg - 2);
                  const isStrong = g.student_avg >= 14;
                  return (
                    <div key={i} className={`flex items-center justify-between px-4 py-2.5 ${i > 0 ? 'border-t border-border dark:border-slate-700' : ''}`}>
                      <span className="text-sm">{g.subject}</span>
                      <div className="flex items-center gap-3">
                        {g.class_avg && (
                          <span className="text-xs text-texte-light dark:text-slate-400">cl: {g.class_avg}</span>
                        )}
                        <span className={`text-sm font-medium ${isWeak ? 'text-orange-600' : isStrong ? 'text-green-600' : 'text-texte'}`}>
                          {g.student_avg}/20
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}
