import { useState, useEffect, useCallback } from 'react';
import api from '../../api/client';
import LoginForm from './LoginForm';
import HomeworkView from './HomeworkView';
import GradesView from './GradesView';
import TimetableView from './TimetableView';

const TABS = [
  { key: 'homework', label: 'Devoirs', icon: '📝' },
  { key: 'grades', label: 'Notes', icon: '📊' },
  { key: 'timetable', label: 'Emploi du temps', icon: '🕐' },
];

export default function EcoleDirectePage() {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('homework');
  const [selectedStudent, setSelectedStudent] = useState(null);

  const checkStatus = useCallback(async () => {
    setLoading(true);
    try {
      const res = await api.get('/ecoledirecte/status');
      setStatus(res.data);
      // Auto-select first active student
      const activeAccounts = (res.data.accounts || []).filter(a => a.sessionActive);
      setSelectedStudent(prev => prev || activeAccounts[0] || null);
    } catch {
      setStatus({ connected: false, accounts: [] });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkStatus();
  }, [checkStatus]);

  async function handleLogout() {
    const account = status?.accounts?.[0];
    if (account) {
      await api.post('/ecoledirecte/logout', { username: account.username });
    }
    setSelectedStudent(null);
    checkStatus();
  }

  if (loading) {
    return (
      <div className="text-center py-12">
        <p className="text-3xl animate-spin">🔄</p>
        <p className="text-sm text-texte-light dark:text-slate-400 mt-2">Chargement...</p>
      </div>
    );
  }

  // Not connected - show login
  const isConnected = status?.connected && status?.accounts?.some(a => a.sessionActive);

  if (!isConnected) {
    return (
      <div>
        <h2 className="text-xl font-bold mb-1">EcoleDirecte</h2>
        <p className="text-sm text-texte-light dark:text-slate-400 mb-6">
          Connectez-vous pour voir les devoirs, notes et emploi du temps.
        </p>
        <LoginForm onSuccess={checkStatus} savedAccount={status?.accounts?.[0]} />
      </div>
    );
  }

  const activeAccounts = status.accounts.filter(a => a.sessionActive);

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold">EcoleDirecte</h2>
        </div>
        <button
          onClick={handleLogout}
          className="text-xs text-red-500 border border-red-200 px-2 py-1 rounded-lg"
        >
          Deconnecter
        </button>
      </div>

      {/* Child selector */}
      {activeAccounts.length > 1 && (
        <div className="flex gap-2">
          {activeAccounts.map(account => (
            <button
              key={account.studentId}
              onClick={() => setSelectedStudent(account)}
              className={`flex-1 py-2.5 px-3 rounded-xl text-sm font-semibold transition-all ${
                selectedStudent?.studentId === account.studentId
                  ? 'bg-accent text-white shadow-sm'
                  : 'bg-blanc dark:bg-slate-900 border border-border dark:border-slate-700 text-texte-light dark:text-slate-400 hover:border-accent'
              }`}
            >
              <div>{account.studentName?.split(' ')[0]}</div>
              <div className={`text-xs mt-0.5 ${
                selectedStudent?.studentId === account.studentId ? 'text-white/80' : 'text-texte-light dark:text-slate-400'
              }`}>
                {account.studentClass}
              </div>
            </button>
          ))}
        </div>
      )}

      {/* Single child info */}
      {activeAccounts.length === 1 && selectedStudent && (
        <p className="text-sm text-texte-light dark:text-slate-400">
          {selectedStudent.studentName} - {selectedStudent.studentClass || 'Classe'}
        </p>
      )}

      {/* Tabs */}
      <div className="flex bg-blanc dark:bg-slate-900 rounded-xl border border-border dark:border-slate-700 p-1 gap-1">
        {TABS.map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`flex-1 py-2 rounded-lg text-xs font-semibold transition-colors ${
              activeTab === tab.key
                ? 'bg-accent text-white'
                : 'text-texte-light dark:text-slate-400 hover:bg-accent-light'
            }`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* Content - key forces remount when student changes */}
      {selectedStudent && (
        <div key={selectedStudent.studentId}>
          {activeTab === 'homework' && <HomeworkView studentId={selectedStudent.studentId} />}
          {activeTab === 'grades' && <GradesView studentId={selectedStudent.studentId} />}
          {activeTab === 'timetable' && <TimetableView studentId={selectedStudent.studentId} />}
        </div>
      )}
    </div>
  );
}
