import { NavLink } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';

export default function BottomNav() {
  const { isParent } = useFamily();

  const tabs = isParent
    ? [
        { path: '/', label: 'Aujourd’hui', icon: '📅' },
        { path: '/bilan', label: 'Bilan Foxie', icon: '📊' },
        { path: '/reglages', label: 'Réglages', icon: '⚙️' },
      ]
    : [
        { path: '/', label: 'Accueil', icon: '🏠' },
        { path: '/devoirs', label: 'Mes devoirs', icon: '📝' },
        { path: '/defi', label: 'Défi du soir', icon: '🎮' },
        { path: '/progres', label: 'Mes progrès', icon: '📈' },
      ];

  return (
    <nav
      className="fixed bottom-0 left-0 right-0 bg-blanc/95 dark:bg-slate-900/95 backdrop-blur-sm border-t border-border dark:border-slate-700 z-40"
      style={{ paddingBottom: 'env(safe-area-inset-bottom, 0px)' }}
    >
      <div className="max-w-lg mx-auto flex justify-around">
        {tabs.map(tab => (
          <NavLink
            key={tab.path}
            to={tab.path}
            className={({ isActive }) =>
              `flex flex-col items-center py-2 px-3 transition-colors min-h-[48px] justify-center flex-1 ${
                isActive ? 'text-accent font-medium' : 'text-texte-light dark:text-slate-400'
              }`
            }
            end={tab.path === '/'}
          >
            <span className="text-2xl">{tab.icon}</span>
            <span className="text-[11px] mt-0.5">{tab.label}</span>
          </NavLink>
        ))}
      </div>
    </nav>
  );
}
