import { useState, useEffect, useCallback } from 'react';
import api from '../../api/client';

const TYPE_ICONS = { qcm: '🔘', vrai_faux: '✅', application: '✏️', situation: '🧩', erreur: '🔍', completement: '📝', calcul: '🔢', texte_court: '💬' };
const TYPE_LABELS = { qcm: 'QCM', vrai_faux: 'Vrai / Faux', application: 'Application', situation: 'Mise en situation', erreur: 'Trouve l\'erreur', completement: 'Complète', calcul: 'Calcul', texte_court: 'Réponse courte' };
const FREE_TEXT_TYPES = ['application', 'situation', 'erreur', 'completement', 'calcul', 'texte_court'];

export default function FicheExercisePlayer({ ficheId, ficheTitle, memberId, onClose }) {
  const [exercises, setExercises] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answer, setAnswer] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [result, setResult] = useState(null);
  const [checking, setChecking] = useState(false);
  const [score, setScore] = useState({ correct: 0, partial: 0, total: 0 });
  const [showSummary, setShowSummary] = useState(false);
  const [showHint, setShowHint] = useState(false);

  const generateExercises = useCallback(async () => {
    setLoading(true);
    try {
      const res = await api.post(`/fiches/${ficheId}/exercises`, { memberId });
      if (res.data.success) {
        setExercises(res.data.exercises);
      }
    } catch (err) {
      console.error('Error generating exercises:', err);
    }
    setLoading(false);
  }, [ficheId, memberId]);

  useEffect(() => {
    generateExercises();
  }, [generateExercises]);

  async function checkAnswer() {
    if (!answer.trim() || checking) return;
    setChecking(true);
    const ex = exercises[currentIdx];

    try {
      // QCM and vrai_faux: check locally
      if (ex.type === 'qcm' || ex.type === 'vrai_faux') {
        const isCorrect = answer.trim().toLowerCase() === ex.answer.trim().toLowerCase();
        setResult({ isCorrect, isPartial: false, explanation: ex.explanation });
        setScore(s => ({
          ...s,
          correct: s.correct + (isCorrect ? 1 : 0),
          total: s.total + 1,
        }));
      } else {
        // calcul / texte_court: use backend Claude check
        const res = await api.post('/fiches/check-answer', {
          question: ex.question,
          userAnswer: answer.trim(),
          correctAnswer: ex.answer,
          acceptKeywords: ex.accept_keywords,
          exerciseType: ex.type,
        });
        setResult(res.data);
        setScore(s => ({
          ...s,
          correct: s.correct + (res.data.isCorrect ? 1 : 0),
          partial: s.partial + (res.data.isPartial && !res.data.isCorrect ? 1 : 0),
          total: s.total + 1,
        }));
      }
      setSubmitted(true);
    } catch {
      setResult({ isCorrect: false, explanation: 'Erreur de connexion' });
      setSubmitted(true);
    }
    setChecking(false);
  }

  function nextExercise() {
    if (currentIdx + 1 >= exercises.length) {
      setShowSummary(true);
    } else {
      setCurrentIdx(i => i + 1);
      setAnswer('');
      setSubmitted(false);
      setResult(null);
      setShowHint(false);
    }
  }

  // Loading
  if (loading) {
    return (
      <div className="fixed inset-0 z-50 bg-fond flex flex-col items-center justify-center" style={{ height: '100dvh' }}>
        <p className="text-4xl animate-bounce mb-4">✏️</p>
        <p className="text-sm font-semibold text-accent">Foxie prépare tes exercices...</p>
        <p className="text-xs text-texte-light mt-1">Basés sur "{ficheTitle}"</p>
      </div>
    );
  }

  if (exercises.length === 0) {
    return (
      <div className="fixed inset-0 z-50 bg-fond flex flex-col items-center justify-center" style={{ height: '100dvh' }}>
        <p className="text-2xl mb-3">😕</p>
        <p className="text-sm text-gray-600">Pas d'exercices générés</p>
        <button onClick={onClose} className="mt-4 text-accent text-sm font-medium">← Retour</button>
      </div>
    );
  }

  // Summary
  if (showSummary) {
    const pct = Math.round((score.correct / score.total) * 100);
    const emoji = pct >= 80 ? '🏆' : pct >= 60 ? '⭐' : pct >= 40 ? '💪' : '🌱';
    return (
      <div className="fixed inset-0 z-50 bg-fond flex flex-col" style={{ height: '100dvh' }}>
        <div className="flex-1 flex flex-col items-center justify-center p-6 space-y-4">
          <p className="text-5xl">{emoji}</p>
          <p className="text-3xl font-bold text-gray-800">{score.correct}/{score.total}</p>
          <p className="text-sm text-gray-500">
            {pct >= 80 ? 'Excellent ! Tu maîtrises cette fiche !' :
             pct >= 60 ? 'Bien joué ! Continue comme ça !' :
             pct >= 40 ? 'Pas mal ! Relis la fiche et réessaie !' :
             'Pas grave, relis la fiche et retente !'}
          </p>
          {score.partial > 0 && (
            <p className="text-xs text-amber-600">{score.partial} réponse{score.partial > 1 ? 's' : ''} partiellement correcte{score.partial > 1 ? 's' : ''}</p>
          )}
          <div className="flex gap-3 pt-4">
            <button onClick={() => {
              setCurrentIdx(0); setAnswer(''); setSubmitted(false); setResult(null);
              setScore({ correct: 0, partial: 0, total: 0 }); setShowSummary(false);
              setShowHint(false); generateExercises();
            }}
              className="bg-accent text-white rounded-xl px-5 py-2.5 text-sm font-semibold active:scale-95">
              Nouveaux exercices
            </button>
            <button onClick={onClose}
              className="bg-white border border-gray-200 rounded-xl px-5 py-2.5 text-sm font-semibold text-gray-700 active:scale-95">
              Fermer
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Exercise screen
  const ex = exercises[currentIdx];

  return (
    <div className="fixed inset-0 z-50 bg-fond flex flex-col" style={{ height: '100dvh' }}>
      {/* Header */}
      <div className="bg-white border-b border-gray-100 px-4 py-3 shrink-0">
        <div className="flex items-center justify-between">
          <button onClick={onClose} className="text-accent text-sm font-medium">← Fermer</button>
          <span className="text-xs text-gray-400">{currentIdx + 1}/{exercises.length}</span>
        </div>
        {/* Progress bar */}
        <div className="mt-2 h-1.5 bg-gray-100 rounded-full overflow-hidden">
          <div className="h-full bg-accent rounded-full transition-all duration-300"
            style={{ width: `${((currentIdx + (submitted ? 1 : 0)) / exercises.length) * 100}%` }} />
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="max-w-lg mx-auto space-y-4">
          {/* Type badge + section */}
          <div className="flex items-center gap-2">
            <span className="text-xs bg-accent/10 text-accent px-2.5 py-1 rounded-full font-medium">
              {TYPE_ICONS[ex.type]} {TYPE_LABELS[ex.type] || ex.type}
            </span>
            {ex.fiche_section && (
              <span className="text-xs text-gray-400">📖 {ex.fiche_section}</span>
            )}
          </div>

          {/* Question */}
          <div className="bg-white rounded-2xl p-4 border border-gray-100 shadow-sm">
            <p className="text-base font-medium text-gray-800 leading-relaxed">{ex.question}</p>
          </div>

          {/* Hint */}
          {ex.hint && !submitted && (
            <div>
              {showHint ? (
                <p className="text-xs bg-amber-50 text-amber-700 rounded-lg px-3 py-2 border border-amber-100">💡 {ex.hint}</p>
              ) : (
                <button onClick={() => setShowHint(true)} className="text-xs text-accent underline">💡 Indice</button>
              )}
            </div>
          )}

          {/* Answer input */}
          {!submitted && (
            <>
              {ex.type === 'qcm' && (
                <div className="space-y-2">
                  {ex.choices?.map((choice, i) => (
                    <button key={i} onClick={() => setAnswer(choice)}
                      className={`w-full text-left p-3.5 rounded-xl border text-sm font-medium transition-all active:scale-[0.98] ${
                        answer === choice
                          ? 'bg-accent text-white border-accent'
                          : 'bg-white border-gray-200 text-gray-700 hover:border-accent/40'
                      }`}>
                      <span className="text-gray-400 mr-2">{String.fromCharCode(65 + i)}.</span>
                      {choice}
                    </button>
                  ))}
                </div>
              )}

              {ex.type === 'vrai_faux' && (
                <div className="flex gap-3">
                  {['vrai', 'faux'].map(v => (
                    <button key={v} onClick={() => setAnswer(v)}
                      className={`flex-1 p-4 rounded-xl border text-sm font-bold transition-all active:scale-95 ${
                        answer === v
                          ? 'bg-accent text-white border-accent'
                          : 'bg-white border-gray-200 text-gray-700'
                      }`}>
                      {v === 'vrai' ? '✅ Vrai' : '❌ Faux'}
                    </button>
                  ))}
                </div>
              )}

              {FREE_TEXT_TYPES.includes(ex.type) && (
                <div className="space-y-2">
                  <input
                    type="text"
                    value={answer}
                    onChange={e => setAnswer(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') checkAnswer(); }}
                    placeholder={
                      ex.type === 'application' || ex.type === 'calcul' ? 'Ta réponse...' :
                      ex.type === 'erreur' ? 'La bonne réponse est...' :
                      ex.type === 'completement' ? 'Complète ici...' :
                      ex.type === 'situation' ? 'Ta réponse (avec le raisonnement)...' :
                      'Ta réponse...'
                    }
                    className="w-full bg-white border border-gray-200 rounded-xl px-4 py-3.5 text-base outline-none focus:border-accent"
                    autoFocus
                  />
                </div>
              )}
            </>
          )}

          {/* Submit button (for non-auto-submit types) */}
          {!submitted && FREE_TEXT_TYPES.includes(ex.type) && (
            <button onClick={checkAnswer} disabled={!answer.trim() || checking}
              className="w-full bg-accent text-white rounded-xl py-3.5 font-semibold text-sm active:scale-[0.98] disabled:opacity-50">
              {checking ? '🧠 Correction...' : 'Valider'}
            </button>
          )}

          {/* Auto-submit for QCM/vrai_faux when selected */}
          {!submitted && (ex.type === 'qcm' || ex.type === 'vrai_faux') && answer && (
            <button onClick={checkAnswer} disabled={checking}
              className="w-full bg-accent text-white rounded-xl py-3.5 font-semibold text-sm active:scale-[0.98] disabled:opacity-50">
              {checking ? '🧠 Correction...' : 'Valider'}
            </button>
          )}

          {/* Result */}
          {submitted && result && (
            <div className={`rounded-2xl p-4 border ${
              result.isCorrect ? 'bg-green-50 border-green-200' :
              result.isPartial ? 'bg-amber-50 border-amber-200' :
              'bg-red-50 border-red-200'
            }`}>
              <div className="flex items-center gap-2 mb-2">
                <span className="text-2xl">
                  {result.isCorrect ? '🎉' : result.isPartial ? '🤔' : '💪'}
                </span>
                <p className={`font-bold text-sm ${
                  result.isCorrect ? 'text-green-700' : result.isPartial ? 'text-amber-700' : 'text-red-600'
                }`}>
                  {result.isCorrect ? 'Bravo !' : result.isPartial ? 'Presque !' : 'Pas tout à fait'}
                </p>
              </div>
              {!result.isCorrect && ex.answer && (
                <p className="text-sm text-gray-700 mb-1">
                  <span className="font-semibold">Réponse :</span> {ex.answer}
                </p>
              )}
              {(result.explanation || ex.explanation) && (
                <p className="text-sm text-gray-600">{result.explanation || ex.explanation}</p>
              )}
            </div>
          )}

          {/* Next button */}
          {submitted && (
            <button onClick={nextExercise}
              className="w-full bg-gray-800 text-white rounded-xl py-3.5 font-semibold text-sm active:scale-[0.98]">
              {currentIdx + 1 >= exercises.length ? '📊 Voir le résultat' : 'Suivant →'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
