import { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import ChatWindow from './ChatWindow';
import api from '../../api/client';

const FREE_CHAT_SUBJECT = 'Foxie';

function getSavedFreeChat(memberId) {
  try {
    const raw = sessionStorage.getItem(`ff_foxie_session_${memberId}`);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function saveFreeChat(memberId, data) {
  try {
    if (data) sessionStorage.setItem(`ff_foxie_session_${memberId}`, JSON.stringify(data));
    else sessionStorage.removeItem(`ff_foxie_session_${memberId}`);
  } catch {}
}

export default function FoxieChatPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const { currentMember } = useFamily();
  const memberId = currentMember?.id;
  const [sessionId, setSessionId] = useState(null);
  const [resumed, setResumed] = useState(false);
  const [error, setError] = useState(false);
  // Question éventuellement tapée/dite depuis l'accueil ("Demande à Foxie...")
  const [initialMessage] = useState(() => location.state?.q || null);

  // On efface l'état d'historique pour ne pas renvoyer la question si on revient.
  useEffect(() => {
    if (location.state?.q) navigate(location.pathname, { replace: true, state: {} });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!memberId) return;
    const saved = getSavedFreeChat(memberId);
    if (saved?.sessionId) {
      setSessionId(saved.sessionId);
      setResumed(true);
      return;
    }
    api.post('/homework/sessions', { memberId, subject: FREE_CHAT_SUBJECT })
      .then(res => {
        const sid = res.data.sessionId;
        setSessionId(sid);
        setResumed(!!res.data.resumed);
        saveFreeChat(memberId, { sessionId: sid });
      })
      .catch(() => setError(true));
  }, [memberId]);

  function handleBack() {
    saveFreeChat(currentMember.id, null);
    setSessionId(null);
    navigate('/');
  }

  if (!currentMember) return null;

  if (error) {
    return (
      <div className="text-center py-12">
        <p className="text-3xl mb-3">🦊</p>
        <p className="text-sm text-texte-light dark:text-slate-400 mb-2">Foxie n'est pas joignable pour le moment.</p>
        <button onClick={() => navigate('/')} className="text-accent text-sm">← Retour</button>
      </div>
    );
  }

  if (!sessionId) {
    return (
      <div className="text-center py-12">
        <p className="text-3xl animate-pulse mb-2">🦊</p>
        <p className="text-sm text-texte-light dark:text-slate-400">Foxie arrive...</p>
      </div>
    );
  }

  return (
    <ChatWindow
      memberId={currentMember.id}
      sessionId={sessionId}
      subject={FREE_CHAT_SUBJECT}
      homeworkContext={null}
      mode={null}
      resumed={resumed}
      onBack={handleBack}
      child={currentMember}
      initialMessage={initialMessage}
    />
  );
}
