import { useState, useEffect } from 'react';
import api, { setAccessToken, getAccessToken } from '../../api/client';

/**
 * Portail d'accès : si le serveur exige un code familial et qu'on n'a pas de
 * token valide, on affiche l'écran de connexion. Sinon, on rend l'application.
 */
export default function AccessGate({ children }) {
  const [status, setStatus] = useState('checking'); // checking | login | ok
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    api.get('/auth/status')
      .then(res => {
        if (!res.data?.authRequired) return setStatus('ok');
        // Code requis : si on a déjà un token, on tente d'entrer (le 401
        // intercepteur nous renverra ici si le token n'est plus valide).
        setStatus(getAccessToken() ? 'ok' : 'login');
      })
      .catch(() => setStatus('ok')); // serveur injoignable : on laisse l'app gérer
  }, []);

  async function submit(e) {
    e.preventDefault();
    setError('');
    setSubmitting(true);
    try {
      const res = await api.post('/auth/login', { code: code.trim() });
      if (res.data?.success && res.data.token) {
        setAccessToken(res.data.token);
        setStatus('ok');
      } else {
        setError('Code incorrect');
      }
    } catch {
      setError('Code incorrect');
    } finally {
      setSubmitting(false);
    }
  }

  if (status === 'checking') {
    return <div className="min-h-screen bg-[#FAF8F5] dark:bg-slate-950" />;
  }

  if (status === 'login') {
    return (
      <div className="min-h-screen bg-[#FAF8F5] dark:bg-slate-950 flex items-center justify-center px-6">
        <form onSubmit={submit} className="w-full max-w-sm text-center">
          <div className="text-5xl mb-4">🦊</div>
          <h1 className="text-2xl font-medium text-gray-800 dark:text-slate-100">Family Flow</h1>
          <p className="text-base text-gray-400 dark:text-slate-500 mt-1 mb-6">
            Entre le code de la famille
          </p>
          <input
            type="password"
            inputMode="text"
            autoFocus
            value={code}
            onChange={(e) => setCode(e.target.value)}
            placeholder="Code d'accès"
            className="w-full text-center text-lg px-4 py-3 rounded-2xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-gray-800 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-accent/40"
          />
          {error && <p className="text-red-500 text-sm mt-3">{error}</p>}
          <button
            type="submit"
            disabled={submitting || !code.trim()}
            className="w-full mt-4 bg-accent text-white text-lg font-medium px-4 py-3 rounded-2xl active:scale-[0.98] disabled:opacity-50"
          >
            {submitting ? 'Vérification…' : 'Entrer'}
          </button>
        </form>
      </div>
    );
  }

  return children;
}
