import { createContext, useContext, useEffect, useState, useCallback } from 'react';

const ThemeContext = createContext({ dark: false, toggle: () => {}, setDark: () => {} });

const STORAGE_KEY = 'ff_dark_mode';

function readInitial() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'true') return true;
    if (saved === 'false') return false;
  } catch {}
  return false;
}

function applyToDocument(dark) {
  const root = document.documentElement;
  if (dark) root.classList.add('dark');
  else root.classList.remove('dark');
  root.style.colorScheme = dark ? 'dark' : 'light';
}

export function ThemeProvider({ children }) {
  const [dark, setDarkState] = useState(readInitial);

  useEffect(() => {
    applyToDocument(dark);
    try { localStorage.setItem(STORAGE_KEY, String(dark)); } catch {}
  }, [dark]);

  const setDark = useCallback((value) => {
    setDarkState(typeof value === 'function' ? value : !!value);
  }, []);

  const toggle = useCallback(() => setDarkState(v => !v), []);

  return (
    <ThemeContext.Provider value={{ dark, toggle, setDark }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}
