import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { FamilyProvider, useFamily } from './context/FamilyContext';
import { ThemeProvider } from './context/ThemeContext';
import AccessGate from './components/welcome/AccessGate';
import AppShell from './components/layout/AppShell';
import WelcomePage from './components/welcome/WelcomePage';
import DashboardPage from './components/dashboard/DashboardPage';
import ParentDashboardPage from './components/dashboard/ParentDashboardPage';
import MesProgressPage from './components/dashboard/MesProgressPage';
import HomeworkPage from './components/homework/HomeworkPage';
import FoxieChatPage from './components/homework/FoxieChatPage';
import QuizPage from './components/quiz/QuizPage';
import BilanPage from './components/bilan/BilanPage';
import SettingsPage from './components/settings/SettingsPage';
import EcoleDirectePage from './components/ecoledirecte/EcoleDirectePage';
import NotificationSettings from './components/settings/NotificationSettings';

function RequireProfile({ children }) {
  const { currentMember, loading } = useFamily();
  if (loading) return null;
  if (!currentMember) return <Navigate to="/welcome" replace />;
  return children;
}

function RoleRouter() {
  const { isParent } = useFamily();
  return isParent ? <ParentDashboardPage /> : <DashboardPage />;
}

function App() {
  return (
    <ThemeProvider>
    <AccessGate>
    <FamilyProvider>
      <BrowserRouter>
        <Routes>
          <Route path="/welcome" element={<WelcomePage />} />

          <Route element={<RequireProfile><AppShell /></RequireProfile>}>
            <Route path="/" element={<RoleRouter />} />

            {/* Enfant — 3 espaces */}
            <Route path="/foxie" element={<FoxieChatPage />} />
            <Route path="/devoirs" element={<HomeworkPage />} />
            <Route path="/defi" element={<QuizPage />} />
            <Route path="/progres" element={<MesProgressPage />} />

            {/* Parent — 3 espaces */}
            <Route path="/bilan" element={<BilanPage />} />
            <Route path="/reglages" element={<SettingsPage />} />
            <Route path="/reglages/ecole" element={<EcoleDirectePage />} />
            <Route path="/reglages/notifications" element={<NotificationSettings />} />
          </Route>

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </FamilyProvider>
    </AccessGate>
    </ThemeProvider>
  );
}

export default App;
