// Lightweight markdown to React elements converter
// Supports: **bold**, *italic*, `code`, numbered lists, bullet lists, line breaks

export function renderMarkdown(text) {
  if (!text) return null;

  // Split into lines
  const lines = text.split('\n');
  const elements = [];
  let listItems = [];
  let listType = null; // 'ol' or 'ul'

  function flushList() {
    if (listItems.length > 0) {
      if (listType === 'ol') {
        elements.push(
          <ol key={`ol-${elements.length}`} className="list-decimal list-inside space-y-0.5 my-1">
            {listItems.map((item, i) => <li key={i}>{formatInline(item)}</li>)}
          </ol>
        );
      } else {
        elements.push(
          <ul key={`ul-${elements.length}`} className="list-disc list-inside space-y-0.5 my-1">
            {listItems.map((item, i) => <li key={i}>{formatInline(item)}</li>)}
          </ul>
        );
      }
      listItems = [];
      listType = null;
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Numbered list (1. 2. 3.)
    const olMatch = line.match(/^\d+\.\s+(.+)/);
    if (olMatch) {
      if (listType !== 'ol') flushList();
      listType = 'ol';
      listItems.push(olMatch[1]);
      continue;
    }

    // Bullet list (- or • or *)
    const ulMatch = line.match(/^[-•*]\s+(.+)/);
    if (ulMatch) {
      if (listType !== 'ul') flushList();
      listType = 'ul';
      listItems.push(ulMatch[1]);
      continue;
    }

    // Not a list item - flush any pending list
    flushList();

    // Empty line = paragraph break
    if (line.trim() === '') {
      elements.push(<br key={`br-${i}`} />);
      continue;
    }

    // Regular line
    elements.push(
      <span key={`line-${i}`}>
        {formatInline(line)}
        {i < lines.length - 1 && <br />}
      </span>
    );
  }

  flushList();
  return <>{elements}</>;
}

// Format inline markdown: **bold**, *italic*, `code`
function formatInline(text) {
  if (!text) return text;

  const parts = [];
  let remaining = text;
  let key = 0;

  while (remaining.length > 0) {
    // Bold: **text**
    const boldMatch = remaining.match(/\*\*(.+?)\*\*/);
    // Italic: *text*
    const italicMatch = remaining.match(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/);
    // Code: `text`
    const codeMatch = remaining.match(/`(.+?)`/);

    // Find the earliest match
    let earliest = null;
    let earliestIndex = remaining.length;

    if (boldMatch && remaining.indexOf(boldMatch[0]) < earliestIndex) {
      earliest = { type: 'bold', match: boldMatch };
      earliestIndex = remaining.indexOf(boldMatch[0]);
    }
    if (italicMatch && remaining.indexOf(italicMatch[0]) < earliestIndex) {
      earliest = { type: 'italic', match: italicMatch };
      earliestIndex = remaining.indexOf(italicMatch[0]);
    }
    if (codeMatch && remaining.indexOf(codeMatch[0]) < earliestIndex) {
      earliest = { type: 'code', match: codeMatch };
      earliestIndex = remaining.indexOf(codeMatch[0]);
    }

    if (!earliest) {
      parts.push(remaining);
      break;
    }

    // Add text before the match
    if (earliestIndex > 0) {
      parts.push(remaining.slice(0, earliestIndex));
    }

    // Add the formatted element
    if (earliest.type === 'bold') {
      parts.push(<strong key={key++} className="font-bold">{earliest.match[1]}</strong>);
    } else if (earliest.type === 'italic') {
      parts.push(<em key={key++} className="italic">{earliest.match[1]}</em>);
    } else if (earliest.type === 'code') {
      parts.push(<code key={key++} className="bg-accent-light text-accent px-1 py-0.5 rounded text-xs font-mono">{earliest.match[1]}</code>);
    }

    remaining = remaining.slice(earliestIndex + earliest.match[0].length);
  }

  return <>{parts}</>;
}
