export function getSeasonImage() {
  const m = new Date().getMonth();
  const d = new Date().getDate();
  if (m === 11 && d >= 20) return 'https://images.unsplash.com/photo-1512389142860-9c449e58a814?w=800&q=60';
  if (m === 0 && d <= 5) return 'https://images.unsplash.com/photo-1467810563316-b5476525c0f9?w=800&q=60';
  if (m === 9 && d === 31) return 'https://images.unsplash.com/photo-1509557965875-b88c97052f0e?w=800&q=60';
  if (m >= 2 && m <= 4) return 'https://images.unsplash.com/photo-1490750967868-88aa4f44baee?w=800&q=60';
  if (m >= 5 && m <= 7) return 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=60';
  if (m >= 8 && m <= 10) return 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=800&q=60';
  return 'https://images.unsplash.com/photo-1457269449834-928af64c684d?w=800&q=60';
}
