import heic2any from 'heic2any';

/**
 * Convert HEIC/HEIF files to JPEG blob.
 * Returns the original file if not HEIC.
 */
export async function ensureJpeg(file) {
  const name = (file.name || '').toLowerCase();
  const type = (file.type || '').toLowerCase();
  const isHeic = name.endsWith('.heic') || name.endsWith('.heif') ||
                 type === 'image/heic' || type === 'image/heif';

  if (!isHeic) return file;

  try {
    const blob = await heic2any({ blob: file, toType: 'image/jpeg', quality: 0.85 });
    // heic2any can return array or single blob
    const result = Array.isArray(blob) ? blob[0] : blob;
    return new File([result], file.name.replace(/\.heic$/i, '.jpg').replace(/\.heif$/i, '.jpg'), {
      type: 'image/jpeg',
    });
  } catch (err) {
    console.warn('HEIC conversion failed for', file.name, err);
    throw new Error(`Format HEIC non supporté pour ${file.name}. Convertis en JPEG d'abord.`);
  }
}

/**
 * Compress an image file to a data URL (JPEG).
 * Handles HEIC conversion automatically.
 */
export async function compressImage(file, maxDim = 1200, quality = 0.7) {
  const jpegFile = await ensureJpeg(file);

  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let { width, height } = img;
      if (width > maxDim || height > maxDim) {
        const ratio = Math.min(maxDim / width, maxDim / height);
        width = Math.round(width * ratio);
        height = Math.round(height * ratio);
      }
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, width, height);
      const url = canvas.toDataURL('image/jpeg', quality);
      URL.revokeObjectURL(img.src);
      resolve(url);
    };
    img.onerror = () => {
      URL.revokeObjectURL(img.src);
      reject(new Error(`Impossible de lire ${file.name}`));
    };
    img.src = URL.createObjectURL(jpegFile);
  });
}

/**
 * Read a file as base64 string (without data URL prefix).
 * Handles HEIC conversion automatically.
 */
export async function readAsBase64(file) {
  const jpegFile = await ensureJpeg(file);

  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(jpegFile);
  });
}
