// Read a file as base64 (returns raw base64 string, without data: prefix)
function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result;
      const base64 = typeof result === 'string' ? result.replace(/^data:[^;]+;base64,/, '') : '';
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

/* ─── Full-screen Chat — ChatGPT style ─── */
export default function ChatWindow({ memberId, sessionId, subject, homeworkContext, mode, resumed, onBack, child, initialMessage }) {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [firstMessageSent, setFirstMessageSent] = useState(false);
  const [listening, setListening] = useState(false);
  const [voiceMuted, setVoiceMuted] = useState(false);
  const { dark: darkMode, toggle: toggleDarkMode } = useTheme();
  const [showFeedback, setShowFeedback] = useState(false);
  const [feedbackDone, setFeedbackDone] = useState(false);
  const [feedbackStep, setFeedbackStep] = useState('quick'); // quick, text
  const [feedbackText, setFeedbackText] = useState('');
  const [pendingPhotos, setPendingPhotos] = useState([]);
  const [photoPrompt, setPhotoPrompt] = useState(() => getDefaultPhotoPrompt(mode));
  const [photoSubject, setPhotoSubject] = useState(''); // matière choisie pour la photo ('' = auto)
  const subjectOptions = officialSubjects(child?.grade);
  const messagesEndRef = useRef(null);
  const fileInputRef = useRef(null);
  const cameraInputRef = useRef(null);
  const [showPhotoMenu, setShowPhotoMenu] = useState(false);
  const recognitionRef = useRef(null);
  const inputRef = useRef(null);
  const speakingRef = useRef(false);
  const audioUnlockedRef = useRef(false);
  const audioRef = useRef(null);
  const speakIdRef = useRef(0); // verrou: ignore tout audio devenu obsolète
  const initialSentRef = useRef(false); // question d'accueil envoyée une seule fois
  const lastAssistantAtRef = useRef(Date.now());
  const isJunior = (child?.age || 0) <= 9;

  useEffect(() => {
    return () => {
      pendingPhotos.forEach(photo => URL.revokeObjectURL(photo.url));
    };
  }, [pendingPhotos]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading]);

  useEffect(() => {
    let cancelled = false;
    async function init() {
      let restored = false;
      if (sessionId) {
        try {
          const res = await api.get(`/homework/sessions/${sessionId}/messages`);
          const existing = res.data.messages || [];
          if (!cancelled && existing.length > 0) {
            setMessages(existing.map(m => ({ role: m.role, content: m.content })));
            setFirstMessageSent(true);
            lastAssistantAtRef.current = Date.now();
            restored = true;
          }
        } catch {}
      }
      if (cancelled) return;
      if (!restored) {
        if (mode === 'controle') {
          setMessages([{ role: 'assistant', content: `Envoie la photo de ton contrôle corrigé. Je choisis la première erreur utile, puis on avance une par une.` }]);
        } else if (mode === 'oral') {
          setMessages([{ role: 'assistant', content: `Je vais t'aider à préparer ton exposé ou ta présentation 🎤\n\nC'est pour quel sujet ?` }]);
        } else if (homeworkContext) {
          setMessages([{ role: 'assistant', content: isJunior ? `On fait une question à la fois. Dis-moi la première ligne.` : `Je vois que tu as un devoir en **${subject}** :\n\n"${homeworkContext}"\n\nPar quoi tu veux commencer ?` }]);
        } else {
          setMessages([{ role: 'assistant', content: isJunior ? `Tu veux faire un mini-défi ou un calcul ?` : `Sur quoi tu travailles en ${subject} ?` }]);
        }
        lastAssistantAtRef.current = Date.now();
        setFirstMessageSent(false);
        // Pas de lecture auto du message d'accueil (évite latence + autoplay bloqué).
        // Foxie parle quand il répond à l'enfant (après une action = son autorisé).
      }
      // Auto-envoi de la question tapée depuis l'accueil ("Demande à Foxie"),
      // APRÈS la mise en place des messages (sinon la restauration async l'écrase).
      if (!cancelled && initialMessage && !initialSentRef.current) {
        initialSentRef.current = true;
        setTimeout(() => { if (!cancelled) sendQuickAction(initialMessage); }, 300);
      }
    }
    init();
    return () => { cancelled = true; };
  }, [sessionId, subject, homeworkContext, mode]); // eslint-disable-line react-hooks/exhaustive-deps

  const unlockAudio = useCallback(() => {
    if (audioUnlockedRef.current) return;
    audioUnlockedRef.current = true;
    try {
      if (window.speechSynthesis) {
        const unlock = new SpeechSynthesisUtterance(' ');
        unlock.lang = 'fr-FR';
        unlock.volume = 0;
        window.speechSynthesis.speak(unlock);
        window.speechSynthesis.cancel();
      }
    } catch {}
    // Débloque un élément <audio> RÉUTILISÉ pendant le geste utilisateur, pour
    // que la lecture différée (Edge-TTS, ~2s après) ne soit PAS bloquée.
    try {
      if (!audioRef.current) audioRef.current = new Audio();
      const a = audioRef.current;
      a.muted = true;
      a.src = SILENT_AUDIO;
      const p = a.play();
      if (p && p.then) p.then(() => { try { a.pause(); a.currentTime = 0; } catch {} a.muted = false; }).catch(() => { a.muted = false; });
    } catch {}
  }, []);

  const stopVoice = useCallback(() => {
    try { window.speechSynthesis?.cancel(); } catch {}
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    }
    speakingRef.current = false;
  }, []);

  // Secours : voix du navigateur (moins naturelle) UNIQUEMENT si Edge-TTS panne.
  const speakWithBrowser = useCallback((clean, myId) => {
    if (myId !== speakIdRef.current) return; // une lecture plus récente a démarré
    if (!window.speechSynthesis) { speakingRef.current = false; return; }
    const voices = window.speechSynthesis.getVoices();
    const voice = voices.find(v => v.lang === 'fr-FR') || voices.find(v => v.lang.startsWith('fr'));
    if (!voice) { speakingRef.current = false; return; }
    const utterance = new SpeechSynthesisUtterance(clean);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.02;
    utterance.pitch = 1.05;
    utterance.voice = voice;
    utterance.onend = () => { speakingRef.current = false; };
    utterance.onerror = () => { speakingRef.current = false; };
    try {
      window.speechSynthesis.cancel();
      window.speechSynthesis.speak(utterance);
    } catch { speakingRef.current = false; }
  }, []);

  // Voix PRINCIPALE : Edge-TTS (Microsoft Neural "Denise") — naturelle, gratuite.
  const speakWithEdgeTts = useCallback(async (text, myId) => {
    let blob;
    try {
      const res = await fetch(`${API_ROOT}/api/avatar/speak`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-access-token': getAccessToken() },
        body: JSON.stringify({ text, emotion: 'happy' }),
      });
      if (!res.ok) { speakWithBrowser(text, myId); return; }
      blob = await res.blob();
      if (!blob || blob.size < 100) { speakWithBrowser(text, myId); return; }
    } catch {
      speakWithBrowser(text, myId);
      return;
    }
    // Si une lecture plus récente a démarré entre-temps, on abandonne (anti-écho).
    if (myId !== speakIdRef.current) return;
    stopVoice();
    // On RÉUTILISE l'élément débloqué pendant le clic (sinon autoplay bloque).
    if (!audioRef.current) audioRef.current = new Audio();
    const audio = audioRef.current;
    audio.muted = false;
    audio.src = URL.createObjectURL(blob);
    audio.onended = () => { speakingRef.current = false; };
    audio.onerror = () => { speakingRef.current = false; };
    // Échec de lecture (autoplay bloqué) : on reste silencieux, PAS de voix robot.
    try { await audio.play(); } catch { speakingRef.current = false; }
  }, [speakWithBrowser, stopVoice]);

  const makeFoxieSpeak = useCallback((text) => {
    if (voiceMuted) return;
    unlockAudio();
    const myId = ++speakIdRef.current; // invalide toute lecture en cours
    stopVoice();
    speakingRef.current = true;
    const clean = text
      // Notations maths -> prononciation française correcte (avant le reste)
      // Toutes variantes de barre oblique (ASCII + typographiques ⁄ ∕ ／)
      .replace(/(\d)\s*[/⁄∕／]\s*(\d)/g, '$1 sur $2') // 15/21 -> 15 sur 21
      .replace(/(\d)\s*[x×*]\s*(\d)/g, '$1 fois $2')  // 6x7 / 6*7 -> 6 fois 7
      .replace(/(\d)\s*÷\s*(\d)/g, '$1 divisé par $2')
      .replace(/(\d)\s*\+\s*(\d)/g, '$1 plus $2')      // 2+3 -> 2 plus 3
      .replace(/(\d)\s*=\s*/g, '$1 égale ')
      .replace(/²/g, ' au carré ').replace(/³/g, ' au cube ')
      .replace(/```[\s\S]*?```/g, '').replace(/`[^`]+`/g, '')
      .replace(/#{1,6}\s/g, '').replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/\*([^*]+)\*/g, '$1').replace(/__([^_]+)__/g, '$1')
      .replace(/_([^_]+)_/g, '$1').replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      .replace(/[\u{1F300}-\u{1F9FF}\u{2600}-\u{27BF}\u{1FA00}-\u{1FAFF}\u{2702}-\u{27B0}\u{FE00}-\u{FE0F}\u{200D}\u{20E3}]/gu, '')
      .replace(/^[-*•]\s+/gm, '').replace(/^\d+\.\s+/gm, '')
      .replace(/\n{2,}/g, '. ').replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
    if (!clean || clean.length < 5) { speakingRef.current = false; return; }
    // Toujours la voix naturelle Denise en priorité (repli navigateur si panne).
    speakWithEdgeTts(clean, myId);
  }, [voiceMuted, unlockAudio, stopVoice, speakWithEdgeTts]);

  async function sendMessage(e) {
    e.preventDefault();
    if (loading) return;
    if (pendingPhotos.length > 0) {
      await sendPendingPhotos();
      return;
    }
    if (!input.trim()) return;
    unlockAudio();
    const userMsg = input.trim();
    const childResponseTimeMs = Math.max(0, Date.now() - lastAssistantAtRef.current);
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setLoading(true);
    stopVoice();
    try {
      let messageToSend = userMsg;
      if (!firstMessageSent && homeworkContext) {
        messageToSend = `[Mon devoir en ${subject}: "${homeworkContext}"]\n\n${userMsg}`;
        setFirstMessageSent(true);
      }
      const res = await api.post('/homework/chat', { memberId, sessionId, message: messageToSend, subject, mode, childResponseTimeMs });
      const responseText = res.data.response;
      setMessages(prev => [...prev, { role: 'assistant', content: responseText }]);
      lastAssistantAtRef.current = Date.now();
      makeFoxieSpeak(responseText);
      const assistantCount = messages.filter(m => m.role === 'assistant').length + 1;
      if (assistantCount >= 5 && !feedbackDone && !showFeedback) {
        setTimeout(() => setShowFeedback(true), 2000);
      }
    } catch {
      setMessages(prev => [...prev, { role: 'assistant', content: 'Oups, problème. Réessaie !' }]);
    } finally { setLoading(false); }
  }

  function toggleVoice() {
    if (!SpeechRecognition) return;
    unlockAudio();
    if (listening) { recognitionRef.current?.stop(); setListening(false); return; }
    const recognition = new SpeechRecognition();
    recognition.lang = 'fr-FR'; recognition.continuous = false; recognition.interimResults = false;
    recognition.onresult = (e) => setInput(prev => (prev ? prev + ' ' : '') + e.results[0][0].transcript);
    recognition.onend = () => setListening(false);
    recognition.onerror = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start(); setListening(true);
  }

  // Quick actions
  function sendQuickAction(actionMessage) {
    if (loading) return;
    unlockAudio();
    const childResponseTimeMs = Math.max(0, Date.now() - lastAssistantAtRef.current);
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: actionMessage }]);
    setLoading(true);
    stopVoice();
    let messageToSend = actionMessage;
    if (!firstMessageSent && homeworkContext) {
      messageToSend = `[Mon devoir en ${subject}: "${homeworkContext}"]\n\n${actionMessage}`;
      setFirstMessageSent(true);
    }
    api.post('/homework/chat', { memberId, sessionId, message: messageToSend, subject, mode, childResponseTimeMs })
      .then(res => { setMessages(prev => [...prev, { role: 'assistant', content: res.data.response }]); lastAssistantAtRef.current = Date.now(); makeFoxieSpeak(res.data.response); })
      .catch(() => { setMessages(prev => [...prev, { role: 'assistant', content: 'Oups, réessaye !' }]); })
      .finally(() => setLoading(false));
  }

  const [generatingFiche, setGeneratingFiche] = useState(null);
  async function generateFiche(type) {
    setGeneratingFiche(type);
    try {
      const topic = homeworkContext || messages.filter(m => m.role === 'user').map(m => m.content).join(' ').slice(0, 100) || subject;
      const res = await api.post('/fiches/generate', { memberId, subject, topic, type });
      if (res.data.success) {
        let fiche = res.data.fiche;
        if (fiche?.id && !fiche.content) {
          try {
            const detail = await api.get(`/fiches/detail/${fiche.id}`);
            if (detail.data.success) fiche = detail.data.fiche;
          } catch {}
        }

        if (type === 'carte_mentale' && fiche?.content) {
          setMessages(prev => [...prev, {
            role: 'assistant',
            content: `Voici la carte mentale : ${fiche.title}`,
            mindMap: fiche.content,
          }]);
        } else {
          const label = type === 'carte_mentale' ? 'Carte mentale' : 'Fiche';
          setMessages(prev => [...prev, { role: 'assistant', content: `${label} créée : ${fiche?.title || topic}` }]);
        }
      }
    } catch {
      setMessages(prev => [...prev, { role: 'assistant', content: "Je n'ai pas réussi à créer la carte. Réessaie dans un instant." }]);
    } finally { setGeneratingFiche(null); }
  }

  function cancelPendingPhotos() {
    pendingPhotos.forEach(photo => { if (photo.url) URL.revokeObjectURL(photo.url); });
    setPendingPhotos([]);
    setPhotoSubject('');
    setPhotoPrompt(getDefaultPhotoPrompt(mode));
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (cameraInputRef.current) cameraInputRef.current.value = '';
  }

  async function sendPendingPhotos() {
    unlockAudio();
    if (!pendingPhotos.length || loading) return;
    const photosToSend = pendingPhotos;
    const prompt = photoPrompt.trim() || getDefaultPhotoPrompt(mode);
    const childResponseTimeMs = Math.max(0, Date.now() - lastAssistantAtRef.current);
    setLoading(true);
    stopVoice();
    try {
      // Prepare each attachment: compress images, base64 PDFs as-is
      const prepared = [];
      for (const photo of photosToSend) {
        if (photo.kind === 'pdf') {
          const b64 = await fileToBase64(photo.file);
          prepared.push({ kind: 'pdf', base64: b64, name: photo.name });
        } else {
          const dataUrl = await compressImage(photo.file, 1200, 0.7);
          const b64 = dataUrl.replace(/^data:image\/\w+;base64,/, '');
          prepared.push({ kind: 'image', base64: b64, dataUrl });
        }
      }
      // Display the user message in the chat (images as thumbnails; PDFs as filename)
      setMessages(prev => [...prev, {
        role: 'user',
        content: prompt,
        images: prepared.filter(p => p.kind === 'image').map(p => p.dataUrl),
        attachments: prepared.filter(p => p.kind === 'pdf').map(p => ({ name: p.name })),
      }]);
      setPendingPhotos([]);
      setPhotoPrompt(getDefaultPhotoPrompt(mode));
      if (fileInputRef.current) fileInputRef.current.value = '';
      if (cameraInputRef.current) cameraInputRef.current.value = '';

      // Matière choisie au moment de la photo -> classe le document correctement.
      // (photoSubject est la valeur capturée à ce rendu ; on le réinitialise pour la suite.)
      const payload = { memberId, sessionId, message: prompt, subject: photoSubject || subject, mode, childResponseTimeMs };
      setPhotoSubject('');
      const preparedImages = prepared.filter(item => item.kind === 'image').map(item => item.base64);
      const preparedPdfs = prepared.filter(item => item.kind === 'pdf').map(item => ({ base64: item.base64, name: item.name }));
      if (preparedImages.length === 1) payload.image = preparedImages[0];
      if (preparedImages.length > 1) payload.images = preparedImages;
      if (preparedPdfs.length === 1) payload.pdf = preparedPdfs[0].base64;
      if (preparedPdfs.length > 1) payload.pdfs = preparedPdfs;

      const res = await api.post('/homework/chat', payload);
      setMessages(prev => [...prev, { role: 'assistant', content: res.data.response }]);
      lastAssistantAtRef.current = Date.now();
      makeFoxieSpeak(res.data.response);
      photosToSend.forEach(photo => { if (photo.url) URL.revokeObjectURL(photo.url); });
    } catch (err) {
      console.error('Image upload error:', err);
      const errMsg = err?.response?.data?.error || err?.message || 'Erreur inconnue';
      setMessages(prev => [...prev, { role: 'assistant', content: `Erreur avec l'image : ${errMsg}. Réessaie !` }]);
    } finally {
      setLoading(false);
    }
  }

  function handleImageUpload(e) {
    unlockAudio();
    setShowPhotoMenu(false);
    const files = Array.from(e.target.files || []);
    if (!files.length) return;

    // Validate PDF size (~25MB limit for Claude API)
    const tooLarge = files.find(f => f.type === 'application/pdf' && f.size > 25 * 1024 * 1024);
    if (tooLarge) {
      setMessages(prev => [...prev, { role: 'assistant', content: `Le PDF "${tooLarge.name}" est trop gros (${(tooLarge.size / 1024 / 1024).toFixed(1)} MB). Limite : 25 MB.` }]);
      e.target.value = '';
      return;
    }

    pendingPhotos.forEach(photo => URL.revokeObjectURL(photo.url));
    setPendingPhotos(files.map((file, index) => {
      const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);
      return {
        id: `${Date.now()}-${index}`,
        file,
        kind: isPdf ? 'pdf' : 'image',
        name: file.name,
        sizeMB: (file.size / 1024 / 1024).toFixed(1),
        url: isPdf ? null : URL.createObjectURL(file),
      };
    }));
    setPhotoPrompt(getDefaultPhotoPrompt(mode));
  }

  return (
    <div className={`fixed inset-0 z-50 flex flex-col ${darkMode ? 'bg-[#0b1120] text-slate-50' : 'bg-white text-gray-950'}`} style={{ height: '100dvh' }}>
      {/* ── Header with back + quick actions ── */}
      <div className={`border-b shrink-0 ${darkMode ? 'border-slate-700 bg-[#0b1120]' : 'border-gray-100 bg-white'}`}>
        <div className="flex items-center gap-3 px-4 py-2">
          <button onClick={onBack} className="text-accent text-lg font-medium">←</button>
          <span className={`font-medium text-lg flex-1 ${darkMode ? 'text-slate-100' : 'text-gray-800'}`}>{subject}</span>
          <button onClick={toggleDarkMode}
            className={`text-sm w-8 h-8 flex items-center justify-center rounded-full active:scale-90 ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-gray-100 text-gray-500'}`}
            title={darkMode ? 'Mode clair' : 'Mode sombre'}>
            {darkMode ? '☀' : '☾'}
          </button>
          <button onClick={() => {
              unlockAudio();
              if (speakingRef.current) stopVoice();
              setVoiceMuted(m => !m);
            }}
            className={`text-lg w-8 h-8 flex items-center justify-center rounded-full active:scale-90 ${
              voiceMuted ? 'bg-red-950/40 text-red-300' : darkMode ? 'bg-slate-800 text-slate-100' : 'bg-gray-100 text-gray-500'
            }`}
            title={voiceMuted ? 'Activer la voix' : 'Couper la voix'}>
            {voiceMuted ? '🔇' : '🔊'}
          </button>
          {!feedbackDone && messages.length >= 2 && (
            <button onClick={() => { setShowFeedback(true); setFeedbackStep('quick'); }}
              className={`text-xs px-2.5 py-1 rounded-full active:scale-95 ${darkMode ? 'bg-slate-800 text-slate-300' : 'bg-gray-100 text-gray-500'}`}>
              Avis
            </button>
          )}
        </div>
      </div>

      {/* ── Messages — takes all available space ── */}
      <div className="flex-1 overflow-y-auto">
        <div className="max-w-2xl mx-auto py-4">
          {messages.map((msg, i) => (
            <MessageBubble key={i} message={msg} isLast={i === messages.length - 1} darkMode={darkMode} />
          ))}
          {loading && <TypingIndicator />}
          {showFeedback && !feedbackDone && (
            <div className="px-4 py-1.5 animate-chat-in">
              {feedbackStep === 'quick' && (
                <div className="flex items-center gap-1.5 py-1">
                  <span className={`text-xs shrink-0 ${darkMode ? 'text-slate-500' : 'text-gray-400'}`}>Avis :</span>
                  {[
                    { tag: 'top', emoji: '🎯' },
                    { tag: 'trop_dur', emoji: '😵' },
                    { tag: 'pas_compris', emoji: '❓' },
                  ].map(opt => (
                    <button key={opt.tag}
                      onClick={async () => {
                        try {
                          const rating = opt.tag === 'top' ? 5 : (opt.tag === 'pas_compris' || opt.tag === 'erreur') ? 2 : 3;
                          await api.post('/feedback', {
                            memberId, sessionId, type: 'session_feedback', rating,
                            comment: opt.tag, subject,
                            context: JSON.stringify({ tag: opt.tag, messageCount: messages.length }),
                          });
                          setFeedbackDone(true);
                        } catch {}
                      }}
                      className={`text-lg shrink-0 w-8 h-8 flex items-center justify-center rounded-full active:scale-110 transition-transform ${darkMode ? 'hover:bg-slate-800' : 'hover:bg-gray-100'}`}
                      title={opt.tag.replace('_', ' ')}>
                      {opt.emoji}
                    </button>
                  ))}
                  <button onClick={() => setFeedbackStep('text')}
                    className="text-xs text-accent shrink-0 ml-1">✏️</button>
                </div>
              )}
              {feedbackStep === 'text' && (
                <div className="flex items-center gap-2 py-1">
                  <input
                    value={feedbackText}
                    onChange={e => setFeedbackText(e.target.value)}
                    placeholder="Suggestion..."
                    className={`flex-1 border rounded-full px-3 py-1.5 text-sm outline-none focus:border-accent ${darkMode ? 'bg-slate-900 border-slate-700 text-slate-100 placeholder:text-slate-500' : 'bg-gray-50 border-gray-200'}`}
                    autoFocus
                    onKeyDown={async (e) => {
                      if (e.key === 'Enter' && feedbackText.trim()) {
                        try {
                          await api.post('/feedback', {
                            memberId, sessionId, type: 'suggestion', rating: 3,
                            comment: feedbackText.trim(), subject,
                            context: JSON.stringify({ messageCount: messages.length }),
                          });
                          setFeedbackDone(true);
                        } catch {}
                      }
                    }}
                  />
                  <button onClick={async () => {
                    if (!feedbackText.trim()) return;
                    try {
                      await api.post('/feedback', {
                        memberId, sessionId, type: 'suggestion', rating: 3,
                        comment: feedbackText.trim(), subject,
                        context: JSON.stringify({ messageCount: messages.length }),
                      });
                      setFeedbackDone(true);
                    } catch {}
                  }}
                    disabled={!feedbackText.trim()}
                    className="text-sm bg-accent text-white px-3 py-1.5 rounded-full font-medium active:scale-95 disabled:opacity-40 shrink-0">
                    OK
                  </button>
                  <button onClick={() => setFeedbackStep('quick')} className={`${darkMode ? 'text-slate-500' : 'text-gray-400'} text-sm shrink-0`}>✕</button>
                </div>
              )}
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* ── Input bar ── */}
      <div className={`border-t shrink-0 ${darkMode ? 'border-slate-700 bg-[#0b1120]' : 'border-gray-200 bg-white'}`} style={{ paddingBottom: 'max(env(safe-area-inset-bottom, 0px), 8px)' }}>
        <PhotoDraft
          photos={pendingPhotos}
          prompt={photoPrompt}
          setPrompt={setPhotoPrompt}
          onCancel={cancelPendingPhotos}
          darkMode={darkMode}
          subjects={subjectOptions}
          photoSubject={photoSubject}
          setPhotoSubject={setPhotoSubject}
        />
        {mode !== 'oral' && (
          <QuickStudyActions
            darkMode={darkMode}
            disabled={loading}
            generatingFiche={generatingFiche}
            junior={isJunior}
            onMindMap={() => generateFiche('carte_mentale')}
            onPractice={() => sendQuickAction("Donne-moi un exercice court pour pratiquer ce qu'on vient de voir. Corrige-moi après ma réponse.")}
            onMiniChallenge={() => sendQuickAction("Donne-moi un mini-défi très court. Une seule question, puis attends ma réponse.")}
            onOneCalculation={() => sendQuickAction("Donne-moi un seul calcul à faire. Ne donne pas la réponse avant moi.")}
          />
        )}
        {/* Photo menu popover */}
        {showPhotoMenu && (
          <>
            <div
              className="fixed inset-0 z-40"
              onClick={() => setShowPhotoMenu(false)}
              aria-hidden="true"
            />
            <div
              role="menu"
              className={`absolute bottom-16 left-3 z-50 rounded-2xl border shadow-lg overflow-hidden min-w-[200px] ${
                darkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-gray-200'
              }`}
            >
              <label
                className={`flex items-center gap-3 px-4 py-3 cursor-pointer ${
                  darkMode ? 'hover:bg-slate-800 text-slate-100' : 'hover:bg-gray-50 text-gray-800'
                }`}
              >
                <span className="text-xl">📸</span>
                <span className="text-sm font-medium">Prendre une photo</span>
                <input
                  ref={cameraInputRef}
                  type="file"
                  accept="image/*"
                  capture="environment"
                  className="hidden"
                  onChange={handleImageUpload}
                />
              </label>
              <label
                className={`flex items-center gap-3 px-4 py-3 cursor-pointer border-t ${
                  darkMode ? 'border-slate-700 hover:bg-slate-800 text-slate-100' : 'border-gray-100 hover:bg-gray-50 text-gray-800'
                }`}
              >
                <span className="text-xl">🖼️</span>
                <span className="text-sm font-medium">Photo ou PDF</span>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*,.heic,.heif,application/pdf"
                  multiple
                  className="hidden"
                  onChange={handleImageUpload}
                />
              </label>
            </div>
          </>
        )}

        <form onSubmit={sendMessage} className="flex items-center gap-2 px-3 py-2">
          <button
            type="button"
            onClick={() => setShowPhotoMenu(v => !v)}
            aria-label="Ajouter une photo"
            className={`w-10 h-10 flex items-center justify-center text-xl rounded-full shrink-0 ${
              showPhotoMenu
                ? 'bg-accent text-white'
                : darkMode ? 'bg-slate-800 text-slate-200 active:bg-slate-700' : 'bg-gray-100 text-gray-500 active:bg-gray-200'
            }`}
          >
            📷
          </button>

          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder={listening ? 'Écoute...' : 'Écris ton message...'}
            className={`flex-1 text-[16px] outline-none rounded-full px-4 py-2.5 ${darkMode ? 'bg-slate-800 text-slate-50 placeholder:text-slate-400' : 'bg-gray-100 text-gray-950 placeholder:text-gray-400'}`}
            disabled={loading}
          />

          {SpeechRecognition && (
            <button type="button" onClick={toggleVoice}
              className={`w-10 h-10 flex items-center justify-center text-xl rounded-full shrink-0 ${
                listening ? 'bg-red-100 text-red-500 animate-pulse' : darkMode ? 'bg-slate-800 text-slate-200 active:bg-slate-700' : 'bg-gray-100 text-gray-500 active:bg-gray-200'
              }`}>
              🎤
            </button>
          )}

          <button type="submit" disabled={loading || (!input.trim() && pendingPhotos.length === 0)}
            className={`w-10 h-10 flex items-center justify-center rounded-full shrink-0 transition-all ${
              (input.trim() || pendingPhotos.length > 0) && !loading ? 'bg-accent text-white active:scale-90' : 'bg-gray-100 text-gray-300'
            }`}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M5 12h14M12 5l7 7-7 7" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
        </form>
      </div>
    </div>
  );
}
