import { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import api from '../../api/client';

function getGreeting(name) {
  const h = new Date().getHours();
  if (h < 7) return `Bonne nuit ${name}`;
  if (h < 12) return `Bonjour ${name} !`;
  if (h < 14) return `Bon appétit ${name} !`;
  if (h < 18) return `Hey ${name} !`;
  if (h < 21) return `Bonsoir ${name} !`;
  return `Bonne soirée ${name} !`;
}

const HAS_SPEECH_RECOGNITION = !!(window.SpeechRecognition || window.webkitSpeechRecognition);

function useVoiceInput(onResult) {
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef(null);

  const startListening = useCallback(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = 'fr-FR';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (e) => { setListening(false); onResult(e.results[0][0].transcript); };
    recognition.onerror = () => setListening(false);
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }, [onResult]);

  const stopListening = useCallback(() => { recognitionRef.current?.stop(); setListening(false); }, []);
  return { listening, startListening, stopListening, hasRecognition: HAS_SPEECH_RECOGNITION };
}

export default function DashboardPage() {
  const navigate = useNavigate();
  const { currentMember, clearMember } = useFamily();
  const memberId = currentMember?.id;
  const [textInput, setTextInput] = useState('');
  const [homework, setHomework] = useState([]);
  const [loadingHw, setLoadingHw] = useState(true);
  const [defiStatus, setDefiStatus] = useState('5 min pour gagner');
  const [progresSummary, setProgresSummary] = useState('Où j’en suis');

  const loadHomework = useCallback(async () => {
    if (!memberId) return;
    setLoadingHw(true);
    try {
      // Fetch pending homework from KB
      const res = await api.get(`/kb/homework/${memberId}`);
      if (res.data.success) setHomework(res.data.homework || []);
      else setHomework([]);
    } catch { setHomework([]); }
    setLoadingHw(false);
  }, [memberId]);

  // Statut "vivant" des cartes (défi du soir + progrès)
  const loadCardStatus = useCallback(async () => {
    if (!memberId) return;
    // Défi du soir : fait / à faire / bientôt
    try {
      const q = (await api.get('/quiz/today')).data?.quiz;
      if (!q) setDefiStatus('Bientôt disponible');
      else {
        const mine = (q.questions || []).filter(x => x.target_member === memberId);
        if (mine.length === 0) setDefiStatus('Nouveau défi ✨');
        else {
          const done = mine.every(x => (x.answered || []).some(a => a.member_id === memberId));
          setDefiStatus(done ? 'Fait aujourd’hui ✅' : 'À faire ce soir ✨');
        }
      }
    } catch {}
    // Progrès : meilleure matière évaluée + nombre
    try {
      const subs = (await api.get(`/progress/${memberId}`)).data?.subjects || [];
      const evaluated = subs.filter(s => s.evaluated);
      if (evaluated.length === 0) setProgresSummary('Où j’en suis');
      else {
        const best = [...evaluated].sort((a, b) => (b.mastery || 0) - (a.mastery || 0))[0];
        setProgresSummary(`${best.subject} ${best.mastery}★ · ${evaluated.length} évaluée${evaluated.length > 1 ? 's' : ''}`);
      }
    } catch {}
  }, [memberId]);

  useEffect(() => {
    if (memberId) {
      loadHomework();
      loadCardStatus();
    }
  }, [memberId, loadHomework, loadCardStatus]);

  const handleVoiceCommand = useCallback((text) => {
    // Tout ce qui est tapé/dit dans "Demande à Foxie" est envoyé À Foxie
    // (avec la question), pour qu'il réponde — y compris "fais-moi un plan
    // de mes devoirs" (avant, le mot "devoir" renvoyait à la liste des devoirs).
    navigate('/foxie', { state: { q: text } });
  }, [navigate]);

  const { listening, startListening, stopListening, hasRecognition } = useVoiceInput(handleVoiceCommand);

  if (!currentMember) return null;

  function handleTextSubmit(e) {
    e.preventDefault();
    if (!textInput.trim()) return;
    handleVoiceCommand(textInput.trim());
    setTextInput('');
  }

  // Tableau de bord "vivant" : Foxie est dans la barre du haut, les devoirs
  // sont affichés au-dessus. Ici on garde 2 cartes qui apportent un STATUT que
  // la barre du bas ne montre pas (défi du soir + progrès).
  const cards = [
    { label: 'Défi du soir', icon: '🎮', desc: defiStatus, path: '/defi' },
    { label: 'Mes progrès', icon: '📈', desc: progresSummary, path: '/progres' },
  ];

  const urgentHomework = homework.filter(hw => {
    const today = new Date().toISOString().split('T')[0];
    const tomorrowDate = new Date();
    tomorrowDate.setDate(tomorrowDate.getDate() + 1);
    const tomorrow = tomorrowDate.toISOString().split('T')[0];
    return hw.due_date === today || hw.due_date === tomorrow;
  });
  const priorityHomework = urgentHomework[0] || homework[0];

  return (
    <div className="flex flex-col gap-4 pb-4">
      {/* Greeting */}
      <div className="flex items-center justify-between">
        <div>
          <p className="text-xl font-medium text-gray-800 dark:text-slate-100">{getGreeting(currentMember.name)}</p>
          <p className="text-sm text-gray-500 dark:text-slate-400">Choisis ton devoir, puis avance étape par étape</p>
        </div>
        <button onClick={() => { clearMember(); navigate('/welcome', { replace: true }); }}
          className="text-sm text-accent bg-accent/10 px-3 py-1.5 rounded-full">
          Changer
        </button>
      </div>

      {/* Quick input */}
      <form onSubmit={handleTextSubmit}>
        <div className="flex items-center gap-2 bg-white dark:bg-slate-900 rounded-full border border-gray-200 dark:border-slate-700 shadow-sm px-4 py-2.5">
          <input
            type="text"
            value={textInput}
            onChange={e => setTextInput(e.target.value)}
            placeholder="Demande à Foxie..."
            className="flex-1 bg-transparent outline-none text-base text-gray-700 dark:text-slate-200 placeholder-gray-400"
          />
          {hasRecognition && (
            <button
              type="button"
              onClick={listening ? stopListening : startListening}
              className={`w-10 h-10 rounded-full flex items-center justify-center transition-all shrink-0 ${
                listening ? 'bg-red-500 animate-pulse' : 'bg-accent'
              }`}
            >
              <span className="text-white text-base">{listening ? '⏹' : '🎤'}</span>
            </button>
          )}
          <button
            type="submit"
            disabled={!textInput.trim()}
            className="w-10 h-10 rounded-full bg-accent flex items-center justify-center shrink-0 disabled:opacity-40"
          >
            <span className="text-white text-base">↑</span>
          </button>
        </div>
      </form>
      {listening && <p className="text-base text-red-500 -mt-2">Foxie écoute...</p>}

      {/* Today's priority */}
      {!loadingHw && priorityHomework && (
        <button
          onClick={() => navigate('/devoirs')}
          className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm text-left active:scale-[0.98] transition-transform"
        >
          <p className="text-sm text-gray-400 dark:text-slate-500 mb-1">À faire maintenant</p>
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-lg font-medium text-gray-800 dark:text-slate-100 truncate">{priorityHomework.subject}</p>
              <p className="text-base text-gray-500 dark:text-slate-400 truncate">{priorityHomework.description}</p>
            </div>
            <span className="text-accent text-sm shrink-0 mt-1">Ouvrir</span>
          </div>
        </button>
      )}

      {/* Today's homework */}
      {!loadingHw && homework.length > 0 && (
        <div className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <h3 className="font-medium text-lg text-gray-800 dark:text-slate-100">Devoirs à venir</h3>
            <button onClick={() => navigate('/devoirs')} className="text-base text-accent">Tout voir</button>
          </div>
          <div className="space-y-2">
            {homework.slice(0, 3).map((hw, i) => {
              const isToday = hw.due_date === new Date().toISOString().split('T')[0];
              const isTomorrow = (() => {
                const d = new Date(); d.setDate(d.getDate() + 1);
                return hw.due_date === d.toISOString().split('T')[0];
              })();
              const dateLabel = isToday ? "Aujourd'hui" : isTomorrow ? 'Demain' : new Date(hw.due_date + 'T00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short' });

              return (
                <button key={i} onClick={() => navigate('/devoirs')}
                  className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-gray-50 active:scale-[0.98] text-left">
                  <span className={`w-3 h-3 rounded-full flex-shrink-0 ${isToday ? 'bg-red-400' : isTomorrow ? 'bg-amber-400' : 'bg-gray-300'}`} />
                  <div className="flex-1 min-w-0">
                    <p className="text-base font-medium text-gray-700 dark:text-slate-200 truncate">{hw.subject}</p>
                    <p className="text-base text-gray-500 dark:text-slate-400 truncate">{hw.description}</p>
                  </div>
                  <span className={`text-sm px-2 py-0.5 rounded flex-shrink-0 ${isToday ? 'bg-red-50 text-red-600' : 'text-gray-400 dark:text-slate-500'}`}>
                    {dateLabel}
                  </span>
                </button>
              );
            })}
            {homework.length > 3 && (
              <p className="text-sm text-gray-400 dark:text-slate-500 text-center">+{homework.length - 3} autres devoirs</p>
            )}
          </div>
        </div>
      )}
      {!loadingHw && homework.length === 0 && (
        <div className="bg-green-50/80 dark:bg-emerald-900/30 border border-green-100 dark:border-emerald-700/40 rounded-2xl p-4 text-center">
          <p className="text-base text-gray-700 dark:text-slate-200">✅ Aucun devoir en attente !</p>
        </div>
      )}

      {/* Cartes "tableau de bord" — statut vivant (défi + progrès) */}
      <div className="grid grid-cols-2 gap-3">
        {cards.map(a => (
          <button
            key={a.path}
            onClick={() => navigate(a.path)}
            className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm active:scale-[0.97] transition-transform text-left"
          >
            <span className="text-3xl">{a.icon}</span>
            <p className="font-medium text-lg mt-2 text-gray-800 dark:text-slate-100">{a.label}</p>
            <p className="text-base text-gray-400 dark:text-slate-500 truncate">{a.desc}</p>
          </button>
        ))}
      </div>
    </div>
  );
}
