import { useState, useEffect } from 'react';
import { useFamily } from '../../context/FamilyContext';
import api from '../../api/client';

const SUBJECT_EMOJI = {
  MATHS: '🔢', FRANCAIS: '📖', 'FRANÇAIS': '📖', HISTOIRE: '🏛️',
  'HISTOIRE-GEOGRAPHIE': '🌍', GEOGRAPHIE: '🌍', ANGLAIS: '🇬🇧', ESPAGNOL: '🇪🇸',
  'PHYSIQUE-CHIMIE': '⚗️', SVT: '🌱', SCIENCES: '🔬', TECHNOLOGIE: '🛠️',
  MUSIQUE: '🎵', 'ARTS PLASTIQUES': '🎨', EPS: '🤸',
};

function emojiFor(subject) {
  const key = (subject || '').toUpperCase();
  if (SUBJECT_EMOJI[key]) return SUBJECT_EMOJI[key];
  const match = Object.keys(SUBJECT_EMOJI).find(k => key.includes(k));
  return match ? SUBJECT_EMOJI[match] : '📚';
}

function MasteryStars({ value }) {
  const v = Math.round(value || 0);
  return (
    <span className="text-base" aria-label={`${v} sur 5`}>
      {'★'.repeat(v)}<span className="text-gray-300 dark:text-slate-600">{'★'.repeat(5 - v)}</span>
    </span>
  );
}

export default function MesProgressPage() {
  const { currentMember } = useFamily();
  const memberId = currentMember?.id;
  const [data, setData] = useState(null);
  const [subjects, setSubjects] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!memberId) return;
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const res = await api.get(`/progress/${memberId}`).catch(() => ({ data: {} }));
        if (cancelled) return;
        setData({ level: res.data?.level ?? 1, totalXp: res.data?.totalXp ?? 0 });
        setSubjects(res.data?.subjects || []);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [memberId]);

  if (!currentMember) return null;

  return (
    <div className="flex flex-col gap-4 pb-4">
      <div>
        <p className="text-xl font-medium text-gray-800 dark:text-slate-100">Mes progrès</p>
        <p className="text-sm text-gray-500 dark:text-slate-400">Où tu en es, {currentMember.name} 🦊</p>
      </div>

      {loading ? (
        <p className="text-center text-3xl animate-pulse py-8">🦊</p>
      ) : (
        <>
          {/* Niveau / XP */}
          <div className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-5 shadow-sm flex items-center gap-4">
            <div className="w-16 h-16 rounded-full bg-accent/10 flex items-center justify-center text-2xl font-bold text-accent shrink-0">
              {data?.level ?? 1}
            </div>
            <div className="min-w-0">
              <p className="text-lg font-medium text-gray-800 dark:text-slate-100">Niveau {data?.level ?? 1}</p>
              <p className="text-base text-gray-500 dark:text-slate-400">{data?.totalXp ?? 0} points d'expérience</p>
            </div>
          </div>

          {/* Maîtrise par matière */}
          <div>
            <h2 className="font-medium text-lg text-gray-700 dark:text-slate-200 mb-3">Mes matières</h2>
            {subjects.length === 0 ? (
              <div className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 text-center">
                <p className="text-base text-gray-600 dark:text-slate-300">
                  Travaille avec Foxie ou fais des défis pour remplir tes progrès ! ✨
                </p>
              </div>
            ) : (
              <div className="space-y-2">
                {subjects.map((s, i) => (
                  <div key={i} className="bg-white/90 dark:bg-slate-900 border border-gray-100 dark:border-slate-700 rounded-2xl p-4 shadow-sm flex items-center gap-3">
                    <span className="text-2xl shrink-0">{emojiFor(s.subject)}</span>
                    <div className="flex-1 min-w-0">
                      <p className="text-base font-medium text-gray-800 dark:text-slate-100 truncate">{s.subject}</p>
                      <p className="text-sm text-gray-400 dark:text-slate-500">
                        {s.grade != null ? `Moyenne ${s.grade}/20` : (s.evaluated ? 'Évalué par Foxie' : 'Pas encore de note')}
                      </p>
                    </div>
                    {s.mastery != null ? (
                      <MasteryStars value={s.mastery} />
                    ) : (
                      <span className="text-xs text-gray-400 dark:text-slate-500 shrink-0 bg-gray-100 dark:bg-slate-800 px-2 py-1 rounded-full">à évaluer</span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}
