import { useState, useEffect, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useFamily } from '../../context/FamilyContext';
import { SUBJECTS } from '../../utils/colorMap';
import ChatWindow from './ChatWindow';
import FicheExercisePlayer from '../fiches/FicheExercisePlayer';
import MindMapMarkmap from '../common/MindMapMarkmap';
import api from '../../api/client';

const MANUAL_SUBJECTS = ['Maths', 'Français', 'Sciences', 'Histoire', 'Anglais'];

const FICHE_TYPE_ICONS = { fiche: '📝', carte_mentale: '🧠', flashcards: '🃏' };
const FICHE_TYPE_LABELS = { fiche: 'Fiche', carte_mentale: 'Carte mentale', flashcards: 'Flashcards' };

// Normalize subject names for matching (FRANCAIS ↔ Français, MATHEMATIQUES ↔ Maths, etc.)
function normalizeSubject(s) {
  return (s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove accents
    .replace(/\s+/g, ' ').trim();
}

const SUBJECT_ALIASES = {
  mathematiques: ['maths', 'math', 'mathematiques'],
  francais: ['francais', 'français', 'french'],
  anglais: ['anglais', 'anglais lv1', 'english'],
  espagnol: ['espagnol', 'espagnol lv2'],
  'histoire-geographie': ['histoire', 'geographie', 'histoire-geographie', 'histoire geographie'],
  'physique-chimie': ['physique', 'chimie', 'physique-chimie', 'sciences'],
  svt: ['svt', 'sciences', 'biologie'],
};

function subjectsMatch(a, b) {
  const na = normalizeSubject(a);
  const nb = normalizeSubject(b);
  if (na === nb || na.includes(nb) || nb.includes(na)) return true;
  // Check aliases
  for (const aliases of Object.values(SUBJECT_ALIASES)) {
    const matchA = aliases.some(al => na.includes(al));
    const matchB = aliases.some(al => nb.includes(al));
    if (matchA && matchB) return true;
  }
  return false;
}

function FicheBadges({ fiches, onOpen }) {
  if (!fiches || fiches.length === 0) return null;
  return fiches.map(f => (
    <span key={f.id}
      onClick={e => { e.stopPropagation(); onOpen(f); }}
      className="text-xs bg-purple-50 dark:bg-purple-950/40 text-purple-600 dark:text-purple-300 px-2.5 py-1 rounded-lg font-medium cursor-pointer hover:bg-purple-100 dark:hover:bg-purple-900/40 active:scale-95 transition-colors">
      {FICHE_TYPE_ICONS[f.type] || '📝'} {f.title?.length > 20 ? f.title.slice(0, 20) + '…' : f.title}
    </span>
  ));
}

// Persist active chat session so navigating away and back restores it
function getSavedSession(memberId) {
  try {
    const raw = sessionStorage.getItem(`ff_hw_session_${memberId}`);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function saveSession(memberId, data) {
  try {
    if (data) sessionStorage.setItem(`ff_hw_session_${memberId}`, JSON.stringify(data));
    else sessionStorage.removeItem(`ff_hw_session_${memberId}`);
  } catch {}
}

export default function HomeworkPage() {
  const { currentMember } = useFamily();

  // Restore session from sessionStorage if available
  const saved = currentMember ? getSavedSession(currentMember.id) : null;
  const [selectedSubject, setSelectedSubject] = useState(saved?.subject || null);
  const [selectedHomework, setSelectedHomework] = useState(saved?.homework || null);
  const [sessionId, setSessionId] = useState(saved?.sessionId || null);
  const [sessionMode, setSessionMode] = useState(saved?.mode || null);
  const [sessionResumed, setSessionResumed] = useState(!!saved?.sessionId);
  const [kbData, setKbData] = useState(null);
  const [openFiche, setOpenFiche] = useState(null); // fiche to display inline
  const [ficheContent, setFicheContent] = useState(null);
  const [ficheLoading, setFicheLoading] = useState(false);
  const [exerciseFiche, setExerciseFiche] = useState(null); // fiche for exercise mode

  // Manual homework form state
  const [showAddForm, setShowAddForm] = useState(false);
  const [formSubject, setFormSubject] = useState('Maths');
  const [formDesc, setFormDesc] = useState('');
  const [formDate, setFormDate] = useState('');
  const [formSaving, setFormSaving] = useState(false);

  // History state
  const [showHistory, setShowHistory] = useState(false);
  const [historySessions, setHistorySessions] = useState([]);
  const [historyDetail, setHistoryDetail] = useState(null);
  const [historyLoading, setHistoryLoading] = useState(false);

  // Fiches by subject (for quick links)
  const [fichesBySubject, setFichesBySubject] = useState({});
  const navigate = useNavigate();
  const location = useLocation();

  const selectedChild = currentMember;

  const loadFiches = useCallback(async (memberId) => {
    try {
      const res = await api.get(`/fiches/${memberId}`);
      if (res.data.success) setFichesBySubject(res.data.bySubject || {});
    } catch { setFichesBySubject({}); }
  }, []);

  const loadKbData = useCallback(async (memberId) => {
    try {
      const res = await api.get(`/kb/summary/${memberId}`);
      if (res.data.success) setKbData(res.data);
      else setKbData(null);
    } catch { setKbData(null); }
  }, []);

  // Load KB data + fiches when child changes
  useEffect(() => {
    if (selectedChild) {
      loadKbData(selectedChild.id);
      loadFiches(selectedChild.id);
    } else {
      setKbData(null);
      setFichesBySubject({});
    }
  }, [selectedChild, loadKbData, loadFiches]);

  async function handleOpenFiche(fiche) {
    setOpenFiche(fiche);
    setFicheLoading(true);
    try {
      const res = await api.get(`/fiches/detail/${fiche.id}`);
      if (res.data.success) setFicheContent(res.data.fiche.content);
    } catch { setFicheContent(null); }
    finally { setFicheLoading(false); }
  }

  function closeFiche() {
    setOpenFiche(null);
    setFicheContent(null);
  }

  function getFichesForSubject(subject) {
    return Object.entries(fichesBySubject)
      .filter(([s]) => subjectsMatch(s, subject))
      .flatMap(([, f]) => f);
  }

  async function startSession(subjectKey, homework, mode) {
    setSelectedSubject(subjectKey);
    setSelectedHomework(homework || null);
    setSessionMode(mode || null);
    try {
      const res = await api.post('/homework/sessions', { memberId: selectedChild.id, subject: subjectKey });
      const sid = res.data.sessionId;
      setSessionId(sid);
      setSessionResumed(!!res.data.resumed);
      // Persist so navigating away and back restores chat
      saveSession(selectedChild.id, { sessionId: sid, subject: subjectKey, homework: homework || null, mode: mode || null });
    } catch (e) {
      console.error('Error creating session:', e);
    }
  }

  // Auto-start a session when arriving with a "refaire" payload from the routine page.
  useEffect(() => {
    const refaire = location.state?.refaire;
    if (!refaire || !selectedChild || sessionId) return;
    startSession(refaire.subject, refaire.context);
    navigate(location.pathname, { replace: true });
  }, [selectedChild, sessionId, location.state?.refaire, location.pathname, navigate]); // eslint-disable-line react-hooks/exhaustive-deps

  async function saveManualHomework() {
    if (!formDesc.trim() || !formDate) return;
    setFormSaving(true);
    try {
      await api.post('/kb/homework', { memberId: selectedChild.id, subject: formSubject, description: formDesc.trim(), due_date: formDate });
      setShowAddForm(false); setFormDesc(''); setFormDate('');
      await loadKbData(selectedChild.id);
    } catch (e) { console.error('Error saving homework:', e); }
    finally { setFormSaving(false); }
  }

  // Mark homework as done/undone
  const [doneAnimating, setDoneAnimating] = useState(null); // hw id being animated
  async function markHomeworkDone(hwId, e) {
    e.stopPropagation();
    setDoneAnimating(hwId);
    try {
      const res = await api.put(`/kb/homework/${hwId}/done`, { done: true });
      if (res.data.success && res.data.coinsAwarded > 0) {
        // Brief animation before refreshing
        setTimeout(async () => {
          await loadKbData(selectedChild.id);
          setDoneAnimating(null);
        }, 600);
      } else {
        await loadKbData(selectedChild.id);
        setDoneAnimating(null);
      }
    } catch (err) {
      console.error('Error marking done:', err);
      setDoneAnimating(null);
    }
  }

  async function loadHistory() {
    setHistoryLoading(true);
    try {
      const res = await api.get(`/homework/sessions?memberId=${selectedChild.id}`);
      setHistorySessions(res.data.sessions || []);
      setShowHistory(true);
    } catch (e) { console.error('Error loading history:', e); }
    finally { setHistoryLoading(false); }
  }

  async function loadSessionDetail(session) {
    try {
      const res = await api.get(`/homework/sessions/${session.id}/messages`);
      setHistoryDetail({ session, messages: res.data.messages || [] });
    } catch (e) { console.error('Error loading session messages:', e); }
  }

  function goBack() {
    if (historyDetail) { setHistoryDetail(null); return; }
    if (showHistory) { setShowHistory(false); setHistorySessions([]); return; }
    if (sessionId) {
      setSessionId(null); setSelectedSubject(null); setSelectedHomework(null); setSessionMode(null); setSessionResumed(false);
      saveSession(selectedChild.id, null); // Clear persisted session
    }
  }

  if (!selectedChild) return null;

  const textbooks = kbData?.textbooks || [];
  const bookUrls = {};
  textbooks.forEach(tb => { if (tb.digital_url) bookUrls[tb.subject] = { url: tb.digital_url, title: tb.title }; });

  // Chat view — full screen overlay (ChatGPT style)
  if (sessionId && selectedSubject) {
    return (
      <ChatWindow
        memberId={selectedChild.id}
        sessionId={sessionId}
        subject={selectedSubject}
        homeworkContext={selectedHomework}
        mode={sessionMode}
        resumed={sessionResumed}
        onBack={goBack}
        child={selectedChild}
      />
    );
  }

  // History detail view
  if (historyDetail) {
    const { session, messages } = historyDetail;
    return (
      <div>
        <button onClick={goBack} className="text-accent text-sm mb-3">← Retour</button>
        <h3 className="font-medium text-base mb-1">{session.subject}</h3>
        <p className="text-xs text-texte-light dark:text-slate-400 mb-4">
          {new Date(session.started_at).toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
        </p>
        <div className="space-y-3">
          {messages.map((msg, i) => (
            <div key={i} className={`rounded-xl p-3 text-sm ${msg.role === 'user' ? 'bg-accent/10 ml-6' : 'bg-blanc border border-border dark:border-slate-700 mr-6'}`}>
              <p className="text-xs font-medium mb-1 text-texte-light dark:text-slate-400">{msg.role === 'user' ? selectedChild.name : 'Foxie'}</p>
              <p className="whitespace-pre-wrap text-xs">{msg.content}</p>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // History list view
  if (showHistory) {
    return (
      <div>
        <button onClick={goBack} className="text-accent text-sm mb-3">← Retour</button>
        <h3 className="font-medium text-base mb-4">Historique</h3>
        {historySessions.length === 0 ? (
          <p className="text-texte-light dark:text-slate-400 text-sm text-center py-8">Aucune conversation encore</p>
        ) : (
          <div className="space-y-2">
            {historySessions.map(s => (
              <button key={s.id} onClick={() => loadSessionDetail(s)}
                className="w-full bg-blanc dark:bg-slate-900 rounded-xl p-3.5 border border-border dark:border-slate-700 text-left hover:shadow-sm active:scale-[0.98]">
                <div className="flex items-center gap-2">
                  <span className="font-medium text-sm">{s.subject}</span>
                  <span className="text-xs text-texte-light dark:text-slate-400 ml-auto">
                    {new Date(s.started_at).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })}
                  </span>
                </div>
                <p className="text-xs text-texte-light dark:text-slate-400 mt-0.5">{s.message_count || 0} message{s.message_count !== 1 ? 's' : ''}</p>
              </button>
            ))}
          </div>
        )}
      </div>
    );
  }

  // Main homework view
  const pendingHw = kbData?.pendingHomework || [];
  const hasKbData = pendingHw.length > 0;
  const isVictoire = selectedChild.name === 'Victoire';
  const allFiches = Object.values(fichesBySubject)
    .flat()
    .sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0))
    .slice(0, 8);

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-medium text-lg">Devoirs de {selectedChild.name}</h2>
          <p className="text-xs text-texte-light dark:text-slate-400">{selectedChild.grade}</p>
        </div>
        <button onClick={loadHistory} disabled={historyLoading}
          className="text-xs bg-blanc dark:bg-slate-800 border border-border dark:border-slate-700 text-texte-light dark:text-slate-400 px-3 py-1.5 rounded-lg">
          {historyLoading ? '...' : '📋 Historique'}
        </button>
      </div>

      {/* Manual homework form for Victoire */}
      {isVictoire && (
        <div>
          {showAddForm ? (
            <div className="bg-blanc dark:bg-slate-900 rounded-xl p-4 border border-border dark:border-slate-700 space-y-3">
              <h4 className="font-medium text-sm">Ajouter un devoir</h4>
              <div>
                <label className="text-xs text-texte-light dark:text-slate-400 mb-1 block">Matière</label>
                <select value={formSubject} onChange={e => setFormSubject(e.target.value)}
                  className="w-full border border-border dark:border-slate-700 rounded-lg px-3 py-2 text-base bg-white">
                  {MANUAL_SUBJECTS.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs text-texte-light dark:text-slate-400 mb-1 block">Description</label>
                <textarea value={formDesc} onChange={e => setFormDesc(e.target.value)}
                  placeholder="Ex: Lire pages 12-15 et répondre aux questions..."
                  className="w-full border border-border dark:border-slate-700 rounded-lg px-3 py-2 text-base bg-white resize-none" rows={2} />
              </div>
              <div>
                <label className="text-xs text-texte-light dark:text-slate-400 mb-1 block">Pour le</label>
                <input type="date" value={formDate} onChange={e => setFormDate(e.target.value)}
                  className="w-full border border-border dark:border-slate-700 rounded-lg px-3 py-2 text-base bg-white" />
              </div>
              <div className="flex gap-2">
                <button onClick={saveManualHomework} disabled={formSaving || !formDesc.trim() || !formDate}
                  className="flex-1 bg-accent text-white rounded-lg py-2 text-sm font-medium disabled:opacity-50">
                  {formSaving ? 'Enregistrement...' : 'Enregistrer'}
                </button>
                <button onClick={() => { setShowAddForm(false); setFormDesc(''); setFormDate(''); }}
                  className="px-4 bg-blanc border border-border dark:border-slate-700 rounded-lg py-2 text-sm">Annuler</button>
              </div>
            </div>
          ) : (
            <button onClick={() => setShowAddForm(true)}
              className="w-full bg-accent/10 border border-accent/20 text-accent rounded-xl p-3 text-sm font-medium flex items-center justify-center gap-2">
              + Ajouter un devoir
            </button>
          )}
        </div>
      )}

      {/* Pending homework from EcoleDirecte */}
      {hasKbData && (
        <div className="space-y-2">
          <h3 className="font-medium text-sm text-texte-light dark:text-slate-400">À faire avec Foxie</h3>
          {pendingHw.slice(0, 5).map((hw, i) => {
            const book = bookUrls[hw.subject];
            const isAnimating = doneAnimating === hw.id;
            return (
              <div key={hw.id || i}
                className={`relative bg-blanc dark:bg-slate-900 rounded-xl p-3.5 border border-border dark:border-slate-700 text-left hover:shadow-sm transition-all duration-500 ${isAnimating ? 'scale-95 opacity-50 bg-green-50 border-green-300' : ''}`}>
                <div className="flex items-start gap-2">
                  {/* Done checkbox */}
                  <button
                    onClick={(e) => markHomeworkDone(hw.id, e)}
                    disabled={isAnimating || !hw.id}
                    className={`mt-0.5 flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all duration-300 active:scale-90 ${isAnimating ? 'bg-green-500 border-green-500 text-white' : 'border-gray-300 hover:border-accent hover:bg-accent/10'}`}
                    title="Marquer comme fait">
                    {isAnimating ? (
                      <span className="text-xs">✓</span>
                    ) : (
                      <span className="text-xs text-transparent group-hover:text-accent">✓</span>
                    )}
                  </button>
                  {/* Homework content */}
                  <button onClick={() => startSession(hw.subject, hw.description)} className="flex-1 text-left active:scale-[0.98]">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="w-2 h-2 rounded-full bg-accent" />
                      <span className="font-medium text-sm">{hw.subject}</span>
                      <span className="text-xs text-texte-light dark:text-slate-400 ml-auto">{hw.due_date}</span>
                    </div>
                    <p className="text-xs text-texte-light dark:text-slate-400 line-clamp-2">{hw.description}</p>
                    <div className="flex items-center gap-2 mt-2 flex-wrap">
                      <span className="text-xs bg-accent/10 dark:bg-accent/20 text-accent dark:text-accent-light px-2.5 py-1 rounded-lg">Aide Foxie</span>
                      {book && (
                        <a href={book.url} target="_blank" rel="noopener noreferrer"
                          className="text-xs bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-300 px-2.5 py-1 rounded-lg"
                          onClick={e => e.stopPropagation()}>
                          📖 {book.title}
                        </a>
                      )}
                      <FicheBadges fiches={getFichesForSubject(hw.subject)} onOpen={handleOpenFiche} />
                    </div>
                  </button>
                </div>
                {/* Coin reward badge on animation */}
                {isAnimating && (
                  <div className="absolute top-2 right-3 animate-bounce text-sm font-medium text-amber-500">
                    +10 🪙
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Completed homework */}
      {(kbData?.completedHomework?.length > 0) && (
        <details className="group">
          <summary className="flex items-center gap-2 cursor-pointer text-sm font-medium text-texte-light dark:text-slate-400 py-1">
            <span className="text-green-500">✅</span>
            Devoirs terminés ({kbData.completedHomework.length})
            <span className="ml-auto text-xs group-open:rotate-180 transition-transform">▼</span>
          </summary>
          <div className="space-y-1.5 mt-2">
            {kbData.completedHomework.map((hw, i) => (
              <div key={hw.id || i} className="bg-green-50/50 dark:bg-emerald-900/20 rounded-xl p-3 border border-green-100 dark:border-emerald-700/40 opacity-70">
                <div className="flex items-center gap-2">
                  <span className="w-5 h-5 rounded-full bg-green-500 text-white flex items-center justify-center text-xs flex-shrink-0">✓</span>
                  <span className="font-medium text-sm text-gray-600">{hw.subject}</span>
                  <span className="text-xs text-texte-light dark:text-slate-400 ml-auto">{hw.due_date}</span>
                </div>
                <p className="text-xs text-texte-light dark:text-slate-400 ml-7 line-clamp-1 mt-0.5">{hw.description}</p>
              </div>
            ))}
          </div>
        </details>
      )}

      {allFiches.length > 0 && (
        <details className="group bg-blanc/70 dark:bg-slate-900/70 rounded-xl border border-border dark:border-slate-700 px-3 py-2">
          <summary className="cursor-pointer text-sm text-texte-light dark:text-slate-400 list-none flex items-center justify-between">
            <span>Cartes et fiches</span>
            <span className="text-xs group-open:rotate-180 transition-transform">▼</span>
          </summary>
          <div className="flex flex-wrap gap-2 pt-3">
            {allFiches.map(fiche => (
              <button
                key={fiche.id}
                onClick={() => handleOpenFiche(fiche)}
                className="text-xs bg-purple-50 dark:bg-purple-950/40 text-purple-600 dark:text-purple-300 px-2.5 py-1 rounded-lg font-medium active:scale-95"
              >
                {FICHE_TYPE_ICONS[fiche.type] || '📝'} {fiche.title?.length > 24 ? fiche.title.slice(0, 24) + '…' : fiche.title}
                <span className="sr-only"> {FICHE_TYPE_LABELS[fiche.type] || 'Fiche'}</span>
              </button>
            ))}
          </div>
        </details>
      )}

      {/* Secondary tools */}
      <details className="group bg-blanc/70 dark:bg-slate-900/70 rounded-xl border border-border dark:border-slate-700 px-3 py-2">
        <summary className="cursor-pointer text-sm text-texte-light dark:text-slate-400 list-none flex items-center justify-between">
          <span>Plus d'options</span>
          <span className="text-xs group-open:rotate-180 transition-transform">▼</span>
        </summary>
        <div className="space-y-2 pt-3">
        <button onClick={() => startSession('Expression Orale', null, 'oral')}
          className="w-full bg-green-50 border border-green-200 text-green-800 rounded-xl p-3.5 flex items-center gap-3 active:scale-[0.98]">
          <span className="text-2xl">🎤</span>
          <div className="text-left">
            <p className="font-medium text-sm">Préparer un exposé / oral</p>
            <p className="text-xs opacity-70">Foxie coach ton expression orale</p>
          </div>
        </button>
        <button onClick={() => startSession('Révision', null, 'controle')}
          className="w-full bg-amber-50 border border-amber-200 text-amber-800 rounded-xl p-3.5 flex items-center gap-3 active:scale-[0.98]">
          <span className="text-2xl">📸</span>
          <div className="text-left">
            <p className="font-medium text-sm">Analyser un ancien contrôle</p>
            <p className="text-xs opacity-70">Foxie identifie tes erreurs</p>
          </div>
        </button>
        </div>
      </details>

      {/* Generic subjects as fallback */}
      <details className="group bg-blanc/70 dark:bg-slate-900/70 rounded-xl border border-border dark:border-slate-700 px-3 py-2">
        <summary className="cursor-pointer text-sm text-texte-light dark:text-slate-400 list-none flex items-center justify-between">
          <span>{hasKbData ? 'Choisir une autre matière' : 'Choisir une matière'}</span>
          <span className="text-xs group-open:rotate-180 transition-transform">▼</span>
        </summary>
        <div className="grid grid-cols-3 gap-2">
          {SUBJECTS.map(s => (
            <button key={s.key} onClick={() => startSession(s.key)}
              className="bg-blanc dark:bg-slate-900 rounded-xl p-3 border border-border dark:border-slate-700 text-center hover:shadow-sm active:scale-[0.98]">
              <span className="text-xl">{s.icon}</span>
              <p className="text-xs font-medium mt-1">{s.label}</p>
            </button>
          ))}
        </div>
      </details>
      {/* Fiche viewer modal */}
      {openFiche && (
        <div className="fixed inset-0 bg-black/40 z-50 flex items-end sm:items-center justify-center" onClick={closeFiche}>
          <div className="bg-fond w-full max-h-[85vh] sm:max-w-lg sm:rounded-2xl rounded-t-2xl overflow-hidden flex flex-col"
            onClick={e => e.stopPropagation()}>
            <div className="bg-purple-600 text-white px-4 py-3 flex items-center justify-between shrink-0">
              <div className="min-w-0">
                <p className="font-medium text-sm truncate">{FICHE_TYPE_ICONS[openFiche.type]} {openFiche.title}</p>
                <p className="text-xs text-white/70">{openFiche.subject}</p>
              </div>
              <button onClick={closeFiche} className="text-white/80 hover:text-white text-xl px-2 shrink-0">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-4">
              {ficheLoading && <p className="text-center text-texte-light dark:text-slate-400 py-8">Chargement...</p>}
              {!ficheLoading && ficheContent && openFiche.type === 'fiche' && (
                <div className="space-y-4">
                  {ficheContent.objective && <p className="text-sm text-accent font-medium bg-accent/10 rounded-xl p-3">🎯 {ficheContent.objective}</p>}
                  {ficheContent.sections?.map((s, i) => (
                    <div key={i} className="bg-white dark:bg-slate-900 rounded-xl p-3 border border-gray-100">
                      <p className="font-medium text-sm mb-2">{s.heading}</p>
                      {s.points?.map((p, j) => <p key={j} className="text-sm text-gray-700 dark:text-slate-200 mb-1">• {p}</p>)}
                      {s.example && <p className="text-xs bg-blue-50 text-blue-700 rounded-lg p-2 mt-2">💡 {s.example}</p>}
                      {s.tip && <p className="text-xs bg-amber-50 text-amber-700 rounded-lg p-2 mt-1">✨ {s.tip}</p>}
                    </div>
                  ))}
                  {ficheContent.key_formulas?.length > 0 && (
                    <div className="bg-red-50 rounded-xl p-3 border border-red-100">
                      <p className="font-medium text-sm mb-1">Formules clés</p>
                      {ficheContent.key_formulas.map((f, i) => <p key={i} className="text-sm text-red-700">• {f}</p>)}
                    </div>
                  )}
                  {ficheContent.summary && <p className="text-sm bg-green-50 text-green-700 rounded-xl p-3 border border-green-100">📝 {ficheContent.summary}</p>}
                </div>
              )}
              {!ficheLoading && ficheContent && openFiche.type === 'carte_mentale' && (
                <div className="space-y-3">
                  <p className="font-medium text-center text-lg">{ficheContent.central_topic || ficheContent.central || ficheContent.title}</p>
                  <MindMapMarkmap data={ficheContent} height={420} />
                  {ficheContent.summary && <p className="text-sm bg-green-50 text-green-700 rounded-xl p-3 border border-green-100">📝 {ficheContent.summary}</p>}
                </div>
              )}
              {!ficheLoading && ficheContent && openFiche.type === 'flashcards' && (
                <FlashcardsInline cards={ficheContent.cards || []} />
              )}

              {/* Quiz yourself section */}
              {!ficheLoading && ficheContent?.quiz_yourself?.length > 0 && (
                <div className="mt-4 bg-amber-50 rounded-xl p-3 border border-amber-100">
                  <p className="font-medium text-sm mb-2 text-amber-800">Teste-toi !</p>
                  {ficheContent.quiz_yourself.map((q, i) => (
                    <p key={i} className="text-sm text-amber-700 mb-1">→ {q}</p>
                  ))}
                </div>
              )}

              {/* Action buttons */}
              {!ficheLoading && ficheContent && (
                <div className="mt-4 flex flex-wrap gap-2">
                  <button onClick={() => {
                    closeFiche();
                    startSession(openFiche.subject, `Aide-moi à réviser la fiche "${openFiche.title}"`);
                  }}
                    className="flex-1 bg-accent text-white rounded-xl py-2.5 text-sm font-medium active:scale-[0.98] flex items-center justify-center gap-1.5">
                    💡 Réviser avec Foxie
                  </button>
                  <button onClick={() => {
                    setExerciseFiche({ id: openFiche.id, title: openFiche.title });
                    closeFiche();
                  }}
                    className="flex-1 bg-amber-500 text-white rounded-xl py-2.5 text-sm font-medium active:scale-[0.98] flex items-center justify-center gap-1.5">
                    ✏️ S'exercer
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Exercise player from fiche */}
      {exerciseFiche && (
        <FicheExercisePlayer
          ficheId={exerciseFiche.id}
          ficheTitle={exerciseFiche.title}
          memberId={selectedChild.id}
          onClose={() => setExerciseFiche(null)}
        />
      )}
    </div>
  );
}

// Inline flashcards viewer
function FlashcardsInline({ cards }) {
  const [current, setCurrent] = useState(0);
  const [flipped, setFlipped] = useState(false);
  if (!cards.length) return <p className="text-center text-texte-light dark:text-slate-400">Aucune carte</p>;
  const card = cards[current];
  return (
    <div className="space-y-4">
      <div onClick={() => setFlipped(!flipped)}
        className="bg-white dark:bg-slate-900 rounded-2xl p-6 border-2 border-purple-200 min-h-[180px] flex items-center justify-center cursor-pointer active:scale-[0.98] transition-transform">
        <div className="text-center">
          <p className="text-xs text-purple-400 mb-2">{flipped ? 'RÉPONSE' : 'QUESTION'} — {current + 1}/{cards.length}</p>
          <p className="text-base font-medium">{flipped ? card.answer : card.question}</p>
          {!flipped && card.hint && <p className="text-xs text-amber-500 mt-3">💡 {card.hint}</p>}
        </div>
      </div>
      <p className="text-xs text-center text-texte-light dark:text-slate-400">Touche la carte pour la retourner</p>
      <div className="flex gap-2">
        <button onClick={() => { setCurrent(Math.max(0, current - 1)); setFlipped(false); }}
          disabled={current === 0}
          className="flex-1 bg-gray-100 rounded-xl py-2.5 text-sm disabled:opacity-30">← Précédente</button>
        <button onClick={() => { setCurrent(Math.min(cards.length - 1, current + 1)); setFlipped(false); }}
          disabled={current === cards.length - 1}
          className="flex-1 bg-purple-100 text-purple-700 rounded-xl py-2.5 text-sm disabled:opacity-30">Suivante →</button>
      </div>
    </div>
  );
}
