import { createContext, useContext, useState, useEffect } from 'react';
import api from '../api/client';

const FamilyContext = createContext();

export function FamilyProvider({ children: childrenProp }) {
  const [members, setMembers] = useState([]);
  const [currentMember, setCurrentMember] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get('/family/members').then(res => {
      setMembers(res.data.members);
      // No auto-restore: each launch asks who is using the app (shared family device)
      setCurrentMember(null);
      try { localStorage.removeItem('ff_viewer_id'); } catch {}
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  function selectMember(member) {
    setCurrentMember(member);
  }

  function clearMember() {
    setCurrentMember(null);
  }

  const childMembers = members.filter(m => m.role === 'child');
  const parentMembers = members.filter(m => m.role === 'parent');
  const isParent = currentMember?.role === 'parent';

  return (
    <FamilyContext.Provider value={{
      members,
      childMembers,
      parentMembers,
      currentMember,
      selectMember,
      setCurrentMember: selectMember,
      clearMember,
      isParent,
      loading,
    }}>
      {childrenProp}
    </FamilyContext.Provider>
  );
}

export function useFamily() {
  return useContext(FamilyContext);
}
